import { db } from './firebase';
import { authService } from './authService';

export interface FeedbackData {
  feedback: string;
  rating: number;
  userId: string;
  userEmail: string;
  timestamp: Date;
  status: 'new' | 'reviewed' | 'resolved';
}

class GlobalFeedbackService {
  async submitFeedback(feedback: string, rating: number): Promise<void> {
    try {
      const user = authService.getCurrentUser();

      const feedbackData: FeedbackData = {
        feedback: feedback.trim(),
        rating,
        userId: user?.uid || 'anonymous',
        userEmail: user?.email || 'anonymous',
        timestamp: new Date(),
        status: 'new'
      };

      await db.collection('feedback').add(feedbackData);
      console.log('✅ Feedback submitted successfully');
    } catch (error) {
      console.error('❌ Error submitting feedback:', error);
      throw new Error('Failed to submit feedback');
    }
  }

  async getFeedback(limit: number = 50): Promise<FeedbackData[]> {
    try {
      const snapshot = await db
        .collection('feedback')
        .orderBy('timestamp', 'desc')
        .limit(limit)
        .get();

      return snapshot.docs.map(doc => ({
        ...doc.data(),
        timestamp: doc.data().timestamp.toDate()
      })) as FeedbackData[];
    } catch (error) {
      console.error('❌ Error fetching feedback:', error);
      throw new Error('Failed to fetch feedback');
    }
  }

  async updateFeedbackStatus(feedbackId: string, status: 'new' | 'reviewed' | 'resolved'): Promise<void> {
    try {
      await db.collection('feedback').doc(feedbackId).update({ status });
      console.log('✅ Feedback status updated');
    } catch (error) {
      console.error('❌ Error updating feedback status:', error);
      throw new Error('Failed to update feedback status');
    }
  }
}

export const globalFeedbackService = new GlobalFeedbackService();

