import { auth, db } from './firebase';
import firebase from 'firebase/compat/app';

export interface User {
  uid: string;
  email: string;
  displayName: string;
  photoURL?: string;
  createdAt: Date;
}

class AuthService {
  private currentUser: User | null = null;

  constructor() {
    // Listen to auth state changes
    auth.onAuthStateChanged(async (firebaseUser) => {
      if (firebaseUser) {
        await this.syncUserData(firebaseUser);
      } else {
        this.currentUser = null;
      }
    });
  }

  private async syncUserData(firebaseUser: firebase.User): Promise<void> {
    try {
      const userDoc = await db.collection('users').doc(firebaseUser.uid).get();

      if (!userDoc.exists) {
        // Create new user document
        const newUser: User = {
          uid: firebaseUser.uid,
          email: firebaseUser.email || '',
          displayName: firebaseUser.displayName || firebaseUser.email?.split('@')[0] || 'User',
          photoURL: firebaseUser.photoURL || undefined,
          createdAt: new Date()
        };

        await db.collection('users').doc(firebaseUser.uid).set(newUser);
        this.currentUser = newUser;
      } else {
        this.currentUser = userDoc.data() as User;
      }
    } catch (error) {
      console.error('Error syncing user data:', error);
    }
  }

  async signUp(email: string, password: string, displayName?: string): Promise<User> {
    try {
      const credential = await auth.createUserWithEmailAndPassword(email, password);

      if (!credential.user) {
        throw new Error('Failed to create user');
      }

      // Update display name if provided
      if (displayName) {
        await credential.user.updateProfile({ displayName });
      }

      const user: User = {
        uid: credential.user.uid,
        email: credential.user.email || email,
        displayName: displayName || email.split('@')[0],
        photoURL: credential.user.photoURL || undefined,
        createdAt: new Date()
      };

      // Save to Firestore
      await db.collection('users').doc(user.uid).set(user);
      this.currentUser = user;

      return user;
    } catch (error: any) {
      console.error('Sign up error:', error);
      throw new Error(error.message || 'Failed to sign up');
    }
  }

  async signIn(email: string, password: string): Promise<User> {
    try {
      const credential = await auth.signInWithEmailAndPassword(email, password);

      if (!credential.user) {
        throw new Error('Failed to sign in');
      }

      await this.syncUserData(credential.user);

      if (!this.currentUser) {
        throw new Error('Failed to load user data');
      }

      return this.currentUser;
    } catch (error: any) {
      console.error('Sign in error:', error);
      throw new Error(error.message || 'Failed to sign in');
    }
  }

  async signInWithGoogle(): Promise<User> {
    try {
      const provider = new firebase.auth.GoogleAuthProvider();
      const credential = await auth.signInWithPopup(provider);

      if (!credential.user) {
        throw new Error('Failed to sign in with Google');
      }

      await this.syncUserData(credential.user);

      if (!this.currentUser) {
        throw new Error('Failed to load user data');
      }

      return this.currentUser;
    } catch (error: any) {
      console.error('Google sign in error:', error);
      throw new Error(error.message || 'Failed to sign in with Google');
    }
  }

  async signOut(): Promise<void> {
    try {
      await auth.signOut();
      this.currentUser = null;
    } catch (error: any) {
      console.error('Sign out error:', error);
      throw new Error(error.message || 'Failed to sign out');
    }
  }

  getCurrentUser(): User | null {
    return this.currentUser;
  }

  isAuthenticated(): boolean {
    return this.currentUser !== null && auth.currentUser !== null;
  }

  async updateProfile(updates: Partial<User>): Promise<void> {
    try {
      const user = auth.currentUser;
      if (!user || !this.currentUser) {
        throw new Error('No user signed in');
      }

      // Update Firebase Auth profile
      if (updates.displayName || updates.photoURL) {
        await user.updateProfile({
          displayName: updates.displayName,
          photoURL: updates.photoURL
        });
      }

      // Update Firestore
      await db.collection('users').doc(user.uid).update(updates);

      // Update local state
      this.currentUser = { ...this.currentUser, ...updates };
    } catch (error: any) {
      console.error('Update profile error:', error);
      throw new Error(error.message || 'Failed to update profile');
    }
  }

  async resetPassword(email: string): Promise<void> {
    try {
      await auth.sendPasswordResetEmail(email);
    } catch (error: any) {
      console.error('Password reset error:', error);
      throw new Error(error.message || 'Failed to send password reset email');
    }
  }

  onAuthStateChange(callback: (user: User | null) => void): () => void {
    return auth.onAuthStateChanged(async (firebaseUser) => {
      if (firebaseUser) {
        await this.syncUserData(firebaseUser);
        callback(this.currentUser);
      } else {
        this.currentUser = null;
        callback(null);
      }
    });
  }
}

export const authService = new AuthService();

