        .orderBy('timestamp', 'desc')
        .limit(limit)
        .get();

      return snapshot.docs.map(doc => ({
        ...doc.data(),
        timestamp: doc.data().timestamp.toDate()
      })) as FeedbackData[];
    } catch (error) {
      console.error('❌ Error fetching feedback:', error);
