    if (!credential.user) throw new Error('Failed to create user');

    if (displayName) {
      await updateProfile(credential.user, { displayName });
    }

    const user: User = {
      uid: credential.user.uid,
      email: credential.user.email || email,
      displayName: displayName || email.split('@')[0],
      photoURL: credential.user.photoURL || undefined,
      createdAt: new Date()
    };

    const userRef = doc(db, 'users', user.uid);
    await setDoc(userRef, {
      ...user,
      createdAt: serverTimestamp()
    });

    this.currentUser = user;
    return user;
  }

  async signIn(email: string, password: string): Promise<User> {
    const credential = await signInWithEmailAndPassword(auth, email, password);
    if (!credential.user) throw new Error('Failed to sign in');

    await this.syncUserData(credential.user);
    if (!this.currentUser) throw new Error('Failed to load user data');

    return this.currentUser;
  }

  async signInWithGoogle(): Promise<User> {
    const provider = new GoogleAuthProvider();
    const credential = await signInWithPopup(auth, provider);

    if (!credential.user) throw new Error('Failed to sign in with Google');
    await this.syncUserData(credential.user);
    if (!this.currentUser) throw new Error('Failed to load user data');

    return this.currentUser;
  }

  async signOut(): Promise<void> {
    await firebaseSignOut(auth);
    this.currentUser = null;
  }

  getCurrentUser(): User | null {
    return this.currentUser;
  }

  isAuthenticated(): boolean {
    return this.currentUser !== null && auth.currentUser !== null;
  }

  onAuthStateChange(callback: (user: User | null) => void): () => void {
    return onAuthStateChanged(auth, async (firebaseUser) => {
      if (firebaseUser) {
        await this.syncUserData(firebaseUser);
        callback(this.currentUser);
      } else {
        this.currentUser = null;
        callback(null);
      }
    });
  }
}

