export const login = async (email: string, password_param: string): Promise<UserDetails> => {
    try {
        // 1. Sign In
        const userCredential = await auth.signInWithEmailAndPassword(email, password_param);
        const user = userCredential.user;

        if (!user) {
            throw new Error('Login failed');
        }

        // 2. Fetch User Data from Firestore
        const cloudData = await storageService.loadUserData(user.uid);
        let userDetails = cloudData?.userDetails;

        // Fallback: If no data in Firestore (e.g. legacy or error), reconstruct basic details
        if (!userDetails) {
            userDetails = {
                id: user.uid,
                name: user.displayName || email.split('@')[0],
                email: email,
                educationalLevel: EducationalLevel.UNDERGRADUATE,
                usage: initializeUsage()
            };
            // Heal the missing data
            await storageService.saveUserData(user.uid, { userDetails });
        }

        // 3. Sync Cloud Data to Local Storage (Restore state)
        if (cloudData) {
             if (cloudData.smartPlan) storageService.saveItem('smartPlan', cloudData.smartPlan);
             if (cloudData.notes) storageService.saveItem('notes', cloudData.notes);
             if (cloudData.savedTimetables) storageService.saveItem('savedTimetables', cloudData.savedTimetables);
             if (cloudData.trackedData) storageService.saveItem('trackedData', cloudData.trackedData);
             if (cloudData.notificationSettings) storageService.saveItem('notificationSettings', cloudData.notificationSettings);
        }

        // 4. Cache locally
        const token = createToken(userDetails);
        storageService.saveItem(SESSION_TOKEN_KEY, token);

        return userDetails;
    } catch (error: any) {
        console.error('Login Error:', error);
        throw error;
    }
