        const commentsQuery = db.collection("comments").orderBy("timestamp", "desc").limit(limit);
        return commentsQuery.onSnapshot((snapshot) => {
            const comments = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Comment));
