const parseGeminiResponse = <T>(response: GenerateContentResponse, fallback?: T): T => {
    try {
        const text = response.text?.trim();

        if (!text) throw new Error("Empty response");

        let jsonStr = text;
        if (text.startsWith('```')) {
            const start = text.indexOf('{') > -1 ? text.indexOf('{') : text.indexOf('[');
            const end = text.lastIndexOf('}') > text.lastIndexOf(']') ? text.lastIndexOf('}') : text.lastIndexOf(']');
            if (start > -1 && end > -1) {
                jsonStr = text.substring(start, end + 1);
            }
        }

        return JSON.parse(jsonStr) as T;
    } catch (e) {
        console.error("❌ Parse error:", e, "Response:", response.text?.substring(0, 200));
        if (fallback) return fallback;
        throw new Error("AI response parsing failed. Please try again.");
    }
};

