            let activity = slot.activity;
            const type = slot.type;

            // 1. Force remove location from study slots
            let location = slot.location;
            if (type === 'study') {
                location = undefined;
            }

            // 2. Fix Generic "Study" Names
            if (type === 'study' && (
                activity.toLowerCase() === 'study' ||
                activity.toLowerCase() === 'revision' ||
                activity.toLowerCase().includes('study session')
            )) {
                // Try to find a subject that isn't scheduled yet today
                const matchingGoal = studyGoals.find(goal => 
                    !dayPlan.slots.some(s => s.activity === goal.subject && s !== slot)
                );
                activity = matchingGoal?.subject || studyGoals[0]?.subject || 'General Study';
            }

            // 3. Prioritize Course Codes
            const codeRegex = /\b([A-Z]{2,5}\s?-?\s?\d{3,4}[A-Z]?)\b/i;
            const match = activity.match(codeRegex);

            if (match) {
