        if (!plan || plan.length === 0 || !plan.find(p => p.slots.length > 0)) {
            console.warn("AI returned empty plan. Using fallback.");
            return createFallbackPlan(lectures, agendaItems);
        }

        const processedPlan = postProcessPlan(plan, studyGoals);
        return processedPlan;

    } catch (error) {
        console.error("AI Generation failed, using fallback plan.", error);
        // Fallback: Return a plan with just the fixed items so the user isn't left with nothing
        return createFallbackPlan(lectures, agendaItems);
    }
};

