// ============================================
// FAST PARSER WITH ERROR RECOVERY
// ============================================

const parseGeminiResponse = <T>(response: GenerateContentResponse, fallback?: T): T => {
    try {
        const text = response.text?.trim();

        if (!text) throw new Error("Empty response");

        let jsonStr = text;
        if (text.startsWith('```')) {
            const start = text.indexOf('{') > -1 ? text.indexOf('{') : text.indexOf('[');
            const end = text.lastIndexOf('}') > text.lastIndexOf(']') ? text.lastIndexOf('}') : text.lastIndexOf(']');
            if (start > -1 && end > -1) {
                jsonStr = text.substring(start, end + 1);
            }
        }

        return JSON.parse(jsonStr) as T;
    } catch (e) {
        console.error("❌ Parse error:", e, "Response:", response.text?.substring(0, 200));
        if (fallback) return fallback;
        throw new Error("AI response parsing failed. Please try again.");
    }
};

// ============================================
// FALLBACK GENERATOR
// ============================================

const createFallbackPlan = (lectures: Lecture[], agendaItems: AgendaItem[]): SmartPlan => {
    return DAYS_OF_WEEK.map(day => {
        const dayLectures = lectures.filter(l => l.day === day).map(l => ({
            activity: l.subject,
            startTime: l.startTime,
            endTime: l.endTime,
            location: l.location,
            type: ActivityType.LECTURE,
            isLocked: true
        }));

        const dayAgenda = agendaItems.filter(a => a.day === day).map(a => ({
            activity: a.title,
            startTime: a.startTime,
            endTime: a.endTime,
            location: a.location,
            type: ActivityType.AGENDA,
            isLocked: true
        }));

        return {
            day,
            slots: [...dayLectures, ...dayAgenda].sort((a, b) => 
                new Date(`1970/01/01 ${a.startTime}`).getTime() - new Date(`1970/01/01 ${b.startTime}`).getTime()
            )
        };
    });
};

// ============================================
// OPTIMIZED MODEL SELECTOR
// ============================================

const getOptimalModel = (task: 'fast' | 'balanced' | 'quality'): string => {
    switch (task) {
        case 'fast': return 'gemini-2.0-flash-exp';
        case 'balanced': return 'gemini-2.0-flash-exp';
        case 'quality': return 'gemini-2.0-flash-exp';
        default: return 'gemini-2.0-flash-exp';
    }
};

// ============================================
// HELPER: CLEAN COURSE NAMES
// ============================================

const postProcessPlan = (plan: SmartPlan, studyGoals: StudyGoal[]): SmartPlan => {
    return plan.map(dayPlan => ({
        ...dayPlan,
        slots: dayPlan.slots.map(slot => {
            let activity = slot.activity;
            const type = slot.type;

            // Force lock lectures so they cannot be renamed/changed type in UI
            let isLocked = slot.isLocked;
            if (type === ActivityType.LECTURE) {
                isLocked = true;
            }

            // 1. Force remove location from study slots
            let location = slot.location;
            if (type === 'study') {
                location = undefined;
            }

            // 2. Fix Generic "Study" Names
            if (type === 'study' && (
                activity.toLowerCase() === 'study' ||
                activity.toLowerCase() === 'revision' ||
                activity.toLowerCase().includes('study session')
            )) {
                // Try to find a subject that isn't scheduled yet today
                const matchingGoal = studyGoals.find(goal => 
                    !dayPlan.slots.some(s => s.activity === goal.subject && s !== slot)
                );
                activity = matchingGoal?.subject || studyGoals[0]?.subject || 'General Study';
            }

            // 3. Prioritize Course Codes
            const codeRegex = /\b([A-Z]{2,5}\s?-?\s?\d{3,4}[A-Z]?)\b/i;
            const match = activity.match(codeRegex);

            if (match) {
                const extractedCode = match[0].toUpperCase();
                if (activity.length > 10) {
                    activity = extractedCode;
                }
            } else if (slot.code && slot.code.length < activity.length) {
                activity = slot.code;
            }

            return { ...slot, activity, location, isLocked };
        })
    }));
};

// ============================================
// SMART PLAN GENERATION (FIXED)
// ============================================

export const generateSmartPlan = async (
    userDetails: UserDetails,
    lectures: Lecture[],
    studyGoals: StudyGoal[],
    agendaItems: AgendaItem[],
    generalGoals: string,
    existingPlan?: SmartPlan
): Promise<SmartPlan> => {
    // Collect all constraints
    const subjectsToStudy = studyGoals.map(g => `${g.subject} (${g.hours} hours/week)`).join(", ");

    // Construct a simpler, stricter prompt
    const prompt = `
    You are an expert academic scheduler. Create a weekly schedule (Monday-Sunday) in JSON.

    **INPUTS:**
    1. **LECTURES (FIXED):** ${JSON.stringify(lectures)}
    2. **AGENDA ITEMS (FIXED):** ${JSON.stringify(agendaItems)}
    3. **STUDY GOALS:** ${subjectsToStudy}
    4. **USER PREFERENCES:** "${generalGoals}"
    5. **USER LEVEL:** ${userDetails.educationalLevel}

    **INSTRUCTIONS:**
    1. **MANDATORY:** You MUST include ALL Lectures and ALL Agenda Items exactly as provided. Do not move or delete them. Mark them as 'lecture' and 'agenda' respectively.
    2. **STUDY SESSIONS:** Fill the gaps between fixed events with 'study' sessions to meet the study goals.
       - Use the User Preferences to decide optimal study times (e.g. if they say "no morning study", respect that).
       - Activity name must be the specific subject name (e.g. "Math", "Biology"), NOT just "Study".
    3. **BREAKS/FREE:** Leave some reasonable gaps or explicitly schedule 'break' or 'free' slots, especially around lunch.
    4. **OUTPUT:** Return a JSON array of objects, one for each day of the week.

    **OUTPUT SCHEMA (Strict JSON Array):**
    [
      {
        "day": "Monday",
        "slots": [
          { "activity": "Math 101", "startTime": "09:00 AM", "endTime": "10:00 AM", "type": "lecture", "location": "Room 101" },
          { "activity": "Math Review", "startTime": "10:15 AM", "endTime": "11:15 AM", "type": "study" },
          { "activity": "Lunch", "startTime": "12:00 PM", "endTime": "01:00 PM", "type": "break" },
          { "activity": "Gym", "startTime": "05:00 PM", "endTime": "06:00 PM", "type": "agenda" }
        ]
      }
      ... (for all 7 days)
    ]
    `;

    try {
        const response = await ai.models.generateContent({
            model: getOptimalModel('fast'),
            contents: prompt,
            config: {
                responseMimeType: 'application/json',
                responseSchema: smartPlanSchema,
                temperature: 0.2, // Lower temperature for more deterministic scheduling
                safetySettings,
            },
        });

        const plan = parseGeminiResponse<SmartPlan>(response, []);

        // Validation: If AI returned empty plan or missing days, fallback
        if (!plan || plan.length === 0 || !plan.find(p => p.slots.length > 0)) {
            console.warn("AI returned empty plan. Using fallback.");
            return createFallbackPlan(lectures, agendaItems);
        }

        const processedPlan = postProcessPlan(plan, studyGoals);
        return processedPlan;

    } catch (error) {
        console.error("AI Generation failed, using fallback plan.", error);
        // Fallback: Return a plan with just the fixed items so the user isn't left with nothing
        return createFallbackPlan(lectures, agendaItems);
    }
};

