const parseGeminiResponse = <T>(response: GenerateContentResponse, fallback?: T): T => {
    try {
        const text = response.text?.trim();

        if (!text) throw new Error("Empty response");

        let jsonStr = text;
        if (text.startsWith('```')) {
            const start = text.indexOf('{') > -1 ? text.indexOf('{') : text.indexOf('[');
            const end = text.lastIndexOf('}') > text.lastIndexOf(']') ? text.lastIndexOf('}') : text.lastIndexOf(']');
            if (start > -1 && end > -1) {
                jsonStr = text.substring(start, end + 1);
            }
        }

        return JSON.parse(jsonStr) as T;
    } catch (e) {
        console.error("❌ Parse error:", e, "Response:", response.text?.substring(0, 200));
        if (fallback) return fallback;
        throw new Error("AI response parsing failed. Please try again.");
    }
};

// ============================================
// FALLBACK GENERATOR (ENHANCED)
// ============================================

const minToTime = (min: number) => {
    let h = Math.floor(min / 60);
    const m = min % 60;
    const period = h >= 12 ? 'PM' : 'AM';
    if (h > 12) h -= 12;
    if (h === 0) h = 12;
    return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')} ${period}`;
};

const createFallbackPlan = (lectures: Lecture[], agendaItems: AgendaItem[], studyGoals: StudyGoal[]): SmartPlan => {
    // Round-robin index for study goals
    let goalIndex = 0;
    const subjects = studyGoals.length > 0 ? studyGoals : [{subject: 'General Study', hours: 5, id: 'default'}];

    return DAYS_OF_WEEK.map(day => {
        // 1. Gather all fixed slots
        const fixedSlots: PlanSlot[] = [
            ...lectures.filter(l => l.day === day).map(l => ({ 
                activity: l.subject, 
                startTime: l.startTime, 
                endTime: l.endTime, 
                location: l.location, 
                type: ActivityType.LECTURE, 
                isLocked: true 
            })),
            ...agendaItems.filter(a => a.day === day).map(a => ({ 
                activity: a.title, 
                startTime: a.startTime, 
                endTime: a.endTime, 
                location: a.location, 
                type: ActivityType.AGENDA, 
                isLocked: true 
            }))
        ].sort((a, b) => timeToMinutes(a.startTime) - timeToMinutes(b.startTime));

        const finalSlots: PlanSlot[] = [];
        let currentTime = 8 * 60; // Start day at 8:00 AM
        const dayEnd = 22 * 60;   // End day at 10:00 PM

        fixedSlots.forEach(slot => {
            const start = timeToMinutes(slot.startTime);
            const end = timeToMinutes(slot.endTime);

            // Fill gap before this slot
            if (start > currentTime) {
                const gap = start - currentTime;

                // If gap is large enough (>= 45 mins), insert study + break
                if (gap >= 45) {
                    // Try to schedule 60 min blocks, or fit to gap
                    const studyDuration = Math.min(gap - 15, 60); // Reserve 15 mins for break if possible

                    if (studyDuration >= 30) {
                        finalSlots.push({
                            activity: subjects[goalIndex % subjects.length].subject,
                            startTime: minToTime(currentTime),
                            endTime: minToTime(currentTime + studyDuration),
                            type: ActivityType.STUDY,
                            durationMinutes: studyDuration
                        });
                        goalIndex++;
                        currentTime += studyDuration;

                        // Insert Break
                        const breakDuration = Math.min(start - currentTime, 30);
                        if (breakDuration > 0) {
                            finalSlots.push({
                                activity: 'Break',
                                startTime: minToTime(currentTime),
                                endTime: minToTime(currentTime + breakDuration),
                                type: ActivityType.BREAK,
                                durationMinutes: breakDuration
                            });
                            currentTime += breakDuration;
                        }
                    }
                }
            }

            // Add the fixed slot
            finalSlots.push(slot);
            currentTime = Math.max(currentTime, end);
        });

        // Fill remaining evening time
        if (currentTime < dayEnd) {
             const gap = dayEnd - currentTime;
             if (gap >= 60) {
                 // Add evening study session
                 finalSlots.push({
                     activity: subjects[goalIndex % subjects.length].subject,
                     startTime: minToTime(currentTime),
                     endTime: minToTime(currentTime + 60),
                     type: ActivityType.STUDY,
                     durationMinutes: 60
                 });
                 goalIndex++;
             }
        }

        return {
            day,
            slots: finalSlots
        };
    });
};

// ============================================
// OPTIMIZED MODEL SELECTOR
// ============================================

const getOptimalModel = (task: 'fast' | 'balanced' | 'quality'): string => {
    switch (task) {
        case 'fast': return 'gemini-2.0-flash-exp';
        case 'balanced': return 'gemini-2.0-flash-exp';
        case 'quality': return 'gemini-2.0-flash-exp';
        default: return 'gemini-2.0-flash-exp';
    }
};

// ============================================
// HELPER: CLEAN COURSE NAMES
// ============================================

const postProcessPlan = (plan: SmartPlan, studyGoals: StudyGoal[]): SmartPlan => {
    return plan.map(dayPlan => ({
        ...dayPlan,
        slots: dayPlan.slots.map(slot => {
            let activity = slot.activity;
            const type = slot.type;

            // Force lock lectures so they cannot be renamed/changed type in UI
            let isLocked = slot.isLocked;
            if (type === ActivityType.LECTURE) {
                isLocked = true;
            }

            // 1. Force remove location from study/break slots
            let location = slot.location;
            if (type === 'study' || type === 'break' || type === 'free') {
                location = undefined;
            }

            // 2. Fix Generic "Study" Names
            if (type === 'study' && (
                activity.toLowerCase() === 'study' ||
                activity.toLowerCase() === 'revision' ||
                activity.toLowerCase().includes('study session')
            )) {
                // Try to find a subject that isn't scheduled yet today
                const matchingGoal = studyGoals.find(goal => 
                    !dayPlan.slots.some(s => s.activity === goal.subject && s !== slot)
                );
                activity = matchingGoal?.subject || studyGoals[0]?.subject || 'General Study';
            }

            // 3. Ensure Breaks are labeled correctly
            if (type === 'break' && !activity) {
                activity = 'Break';
            }

            // 4. Prioritize Course Codes
            const codeRegex = /\b([A-Z]{2,5}\s?-?\s?\d{3,4}[A-Z]?)\b/i;
            const match = activity.match(codeRegex);

            if (match) {
                const extractedCode = match[0].toUpperCase();
                if (activity.length > 10) {
                    activity = extractedCode;
                }
            } else if (slot.code && slot.code.length < activity.length) {
                activity = slot.code;
            }

            return { ...slot, activity, location, isLocked };
        })
    }));
};

// ============================================
// SMART PLAN GENERATION (FIXED)
// ============================================

export const generateSmartPlan = async (
    userDetails: UserDetails,
    lectures: Lecture[],
    studyGoals: StudyGoal[],
    agendaItems: AgendaItem[],
    generalGoals: string,
    existingPlan?: SmartPlan
): Promise<SmartPlan> => {
    // Collect all constraints
    const subjectsToStudy = studyGoals.map(g => `${g.subject} (${g.hours} hours/week)`).join(", ");

    // Construct a simpler, stricter prompt with mandatory breaks
    const prompt = `
    You are an expert academic scheduler. Create a weekly schedule (Monday-Sunday) in JSON.

    **INPUTS:**
    1. **FIXED EVENTS (Include ALL):**
       - Lectures: ${JSON.stringify(lectures)}
       - Agenda: ${JSON.stringify(agendaItems)}
    2. **STUDY GOALS:** ${subjectsToStudy}
    3. **USER PREFERENCES (Strictly Follow):** "${generalGoals}"
    4. **USER LEVEL:** ${userDetails.educationalLevel}

    **RULES & INSTRUCTIONS:**
    1. **FIXED ITEMS:** You MUST map all Lectures and Agenda Items to their specific days and times. Type: 'lecture' or 'agenda'.
    2. **STUDY SESSIONS:** Fill gaps with 'study' sessions. Distribute subjects evenly. Type: 'study'.
    3. **MANDATORY BREAKS:** 
       - Schedule a 15-30 minute 'break' after every ~2 hours of activity.
       - Ensure there is a lunch break around 12:00 PM - 2:00 PM if possible.
       - Type: 'break'.
    4. **FREE TIME:** Leave late evenings or times specified in preferences as free. Type: 'free'.

    **OUTPUT FORMAT:**
    Return a JSON array of objects for each day.
    Example slot: { "activity": "Math", "startTime": "09:00 AM", "endTime": "10:00 AM", "type": "study" }
    `;

    try {
        const response = await ai.models.generateContent({
            model: getOptimalModel('fast'),
            contents: prompt,
            config: {
                responseMimeType: 'application/json',
                responseSchema: smartPlanSchema,
                temperature: 0.2, // Lower temperature for more deterministic scheduling
                safetySettings,
            },
        });

        const plan = parseGeminiResponse<SmartPlan>(response, []);

        // Validation: If AI returned empty plan or missing days, fallback
        if (!plan || plan.length === 0 || !plan.find(p => p.slots.length > 0)) {
            console.warn("AI returned empty plan. Using fallback.");
            return createFallbackPlan(lectures, agendaItems, studyGoals);
        }

        const processedPlan = postProcessPlan(plan, studyGoals);
        return processedPlan;

    } catch (error) {
        console.error("AI Generation failed, using fallback plan.", error);
        // Fallback: Return a robust plan ensuring user inputs are respected
        return createFallbackPlan(lectures, agendaItems, studyGoals);
    }
};

