export const solveProblem = async (
    questionText: string,
    imagePart: ImagePart | null,
    outputFormat: string,
    programmingLanguage: string,
    graphInterval?: string,
    graphYInterval?: string,
): Promise<string> => {
    let prompt = `Solve this problem: ${questionText}\nFormat: ${outputFormat}\n`;

    if (outputFormat === 'code') {
        prompt += `Language: ${programmingLanguage}. Return code in a Markdown code block.`;
    } else if (outputFormat === 'latex') {
        prompt += `Return raw LaTeX code wrapped in a markdown code block.`;
    } else if (outputFormat === 'graph') {
        prompt += `Return JSON: {explanation: string, graphFunction: string (e.g. "x^2"), suggestedTitle: string}. ${graphInterval ? `X Range: ${graphInterval}` : ''}`;
    } else {
        prompt += `Provide a step-by-step solution in Markdown with LaTeX for math.`;
    }

    const contents: any = { parts: [{ text: prompt }] };
    if (imagePart) contents.parts.push(imagePart);

    const response = await ai.models.generateContent({
        model: getOptimalModel('quality'),
