const SignUp: React.FC<SignUpProps> = ({ onLogin }) => {
  const { t } = useLanguage();
  const [viewMode, setViewMode] = useState<'signIn' | 'signUp' | 'forgotPassword'>('signIn');

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    confirmPassword: '',
    recoveryQuestion: recoveryQuestions[0],
    recoveryAnswer: '',
  });

  const [showPassword, setShowPassword] = useState(false);
  const [errors, setErrors] = useState<Partial<typeof formData> & { general?: string }>({});
  const [message, setMessage] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    if (errors[name as keyof typeof errors]) {
      setErrors(prev => ({ ...prev, [name]: undefined }));
    }
    setErrors(prev => ({...prev, general: undefined}));
    setMessage('');
  };

  const validate = () => {
    const newErrors: Partial<typeof formData> = {};
    if (viewMode === 'signUp') {
        if (!formData.name.trim()) newErrors.name = t('validation.nameRequired');
        if (!formData.recoveryQuestion) newErrors.recoveryQuestion = t('validation.recoveryQRequired');
        if (!formData.recoveryAnswer.trim()) newErrors.recoveryAnswer = t('validation.recoveryARequired');
    }
    if (viewMode === 'signUp' || viewMode === 'signIn' || viewMode === 'forgotPassword') {
        if (!formData.email.trim()) newErrors.email = t('validation.emailRequired');
        else if (!/\S+@\S+\.\S+/.test(formData.email)) newErrors.email = t('validation.emailInvalid');
    }

    if (viewMode === 'signUp' || viewMode === 'signIn') {
        if (!formData.password) newErrors.password = t('validation.passwordRequired');
        else if (viewMode === 'signUp' && formData.password.length < 6) newErrors.password = t('validation.passwordMinLength');
    }

    if (viewMode === 'signUp' && formData.password !== formData.confirmPassword) {
        newErrors.confirmPassword = t('validation.passwordMismatch');
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) return;

    setIsSubmitting(true);
    setErrors({});
    setMessage('');

    try {
        if (viewMode === 'signUp') {
            const user = await signUp(formData.name, formData.email, formData.password, formData.recoveryQuestion, formData.recoveryAnswer);
            setMessage(t('auth.signupSuccess'));
            setTimeout(() => onLogin(user), 1000);
        } else if (viewMode === 'signIn') {
            const user = await login(formData.email, formData.password);
            setMessage(t('auth.loginSuccess'));
            setTimeout(() => onLogin(user), 500);
        } else if (viewMode === 'forgotPassword') {
            const success = await findUserByEmail(formData.email);
            if (success) {
                setMessage("Password reset link sent to your email.");
                setTimeout(() => setViewMode('signIn'), 3000);
            } else {
                setErrors({ general: t('recovery.error') });
            }
        }
    } catch (error: any) {
        // Robust error extraction
        let errorMsg = '';
        let errorCode = '';

        if (typeof error === 'string') {
            errorMsg = error.toLowerCase();
        } else if (error && typeof error === 'object') {
            errorMsg = (error.message || '').toLowerCase();
            errorCode = (error.code || '').toLowerCase();
        }

        // SignUp specific checks
        if (viewMode === 'signUp' && (errorMsg.includes('email already registered') || errorCode.includes('email-already-in-use'))) {
            setErrors({ email: t('validation.emailExists') });
            setIsSubmitting(false);
            return;
        }

        // Broad Login/Auth Failure Checks for user-friendly message
        const isAuthError = 
            errorMsg.includes('invalid email or password') ||
            errorCode.includes('invalid-credential') ||
            errorCode.includes('user-not-found') ||
            errorCode.includes('wrong-password') ||
            errorCode.includes('invalid-login-credentials') ||
            errorMsg.includes('auth/invalid-credential') ||
            errorMsg.includes('credential is incorrect') ||
            errorMsg.includes('supplied auth credential') ||
            errorMsg.includes('malformed or has expired') ||
            errorCode.includes('auth/too-many-requests');

        if (isAuthError) {
             // Generic friendly message for invalid credentials
             setErrors({ general: t('validation.loginFailed') });
        } else {
            // Clean up the error message for display if it's something else
            let displayMsg = typeof error === 'string' ? error : error.message || 'An unexpected error occurred.';

            // Remove "Firebase: " prefix and code suffix (e.g., "(auth/foo).")
            if (displayMsg.startsWith('Firebase: ')) {
                displayMsg = displayMsg.replace('Firebase: ', '');
            }
            displayMsg = displayMsg.replace(/\s*\(auth\/.*?\)\.?/g, '').trim();

            // Use generic message if cleaning results in empty string or if it's too technical
            if (!displayMsg || displayMsg.toLowerCase().includes('firebase')) {
                 displayMsg = t('validation.loginFailed');
            }

            setErrors({ general: displayMsg });
        }
    } finally {
        setIsSubmitting(false);
    }
  };

  const renderContent = () => {
    const inputClasses = (field: keyof typeof errors) => `w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 bg-white dark:bg-black ${errors[field] ? 'border-red-500 focus:ring-red-500' : 'border-gray-300 dark:border-gray-600 focus:ring-primary'}`;

    if (viewMode === 'forgotPassword') {
        return (
            <div className="space-y-6">
                <div><h2 className="text-center text-3xl font-extrabold">{t('recovery.title')}</h2></div>
                {message ? (
                    <div className="bg-green-100 border border-green-400 text-green-700 px-4 py-3 rounded relative text-center">
                        {message}
                    </div>
                ) : (
                    <form onSubmit={handleSubmit} className="space-y-4 pt-8">
                        <p className="text-center text-sm text-gray-600 dark:text-gray-400">{t('recovery.step1.prompt')}</p>
                        <div><label className="sr-only">{t('auth.email')}</label><input type="email" name="email" value={formData.email} onChange={handleInputChange} className={inputClasses('email')} placeholder="evans@example.com" required />{errors.email && <p className="text-red-500 text-xs mt-1">{errors.email}</p>}</div>

                        <button type="submit" disabled={isSubmitting} className="w-full flex justify-center py-3 px-4 border border-transparent rounded-lg shadow-sm text-sm font-medium text-white bg-amber-500 hover:bg-amber-600 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-amber-500 disabled:opacity-50">
                            {isSubmitting ? <LoadingSpinner /> : "Send Reset Link"}
                        </button>
                        {errors.general && <p className="text-red-500 text-sm mt-2 text-center">{errors.general}</p>}
                    </form>
                )}
                <div className="text-sm text-center">
                    <button onClick={() => { setViewMode('signIn'); setMessage(''); setErrors({}); }} className="font-medium text-primary hover:text-primary-dark dark:text-primary-light dark:hover:text-primary">{t('recovery.backToLogin')}</button>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6">
             <div><h2 className="mt-6 text-center text-3xl font-extrabold">{viewMode === 'signUp' ? t('auth.createAccount') : t('auth.signInToEduBlay')}</h2></div>
             {message && <p className="text-green-500 text-center">{message}</p>}
             <form onSubmit={handleSubmit} className="space-y-4 pt-8">
                {viewMode === 'signUp' && (
                    <>
                        <div><label className="sr-only">{t('auth.fullName')}</label><input type="text" name="name" value={formData.name} onChange={handleInputChange} className={inputClasses('name')} placeholder={t('auth.fullName')} />{errors.name && <p className="text-red-500 text-xs mt-1">{errors.name}</p>}</div>
                    </>
                )}
                <div><label className="sr-only">{t('auth.email')}</label><input type="email" name="email" value={formData.email} onChange={handleInputChange} className={inputClasses('email')} placeholder="evans@example.com" required />{errors.email && <p className="text-red-500 text-xs mt-1">{errors.email}</p>}</div>
                <div className="relative"><label className="sr-only">{t('auth.password')}</label><input type={showPassword ? 'text' : 'password'} name="password" value={formData.password} onChange={handleInputChange} className={inputClasses('password')} placeholder={t('auth.password')} /><button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute inset-y-0 right-0 pr-3 flex items-center text-gray-500">{showPassword ? <EyeOffIcon className="h-5 w-5"/> : <EyeIcon className="h-5 w-5"/>}</button></div>{errors.password && <p className="text-red-500 text-xs mt-1">{errors.password}</p>}
                 {viewMode === 'signUp' && (
                    <>
                    <div><label className="sr-only">{t('auth.confirmPassword')}</label><input type="password" name="confirmPassword" value={formData.confirmPassword} onChange={handleInputChange} className={inputClasses('confirmPassword')} placeholder={t('auth.confirmPassword')} />{errors.confirmPassword && <p className="text-red-500 text-xs mt-1">{errors.confirmPassword}</p>}</div>
                    <div className="pt-2"><label htmlFor="recoveryQuestion" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">{t('recovery.question')}</label><select name="recoveryQuestion" value={formData.recoveryQuestion} onChange={handleInputChange} className={inputClasses('recoveryQuestion')}>{recoveryQuestions.map(q => <option key={q} value={q}>{t(q as any)}</option>)}</select></div>
                    <div><label className="sr-only">{t('recovery.answer')}</label><input type="text" name="recoveryAnswer" value={formData.recoveryAnswer} onChange={handleInputChange} className={inputClasses('recoveryAnswer')} placeholder={t('recovery.answer')} required />{errors.recoveryAnswer && <p className="text-red-500 text-xs mt-1">{errors.recoveryAnswer}</p>}</div>
                    </>
                )}
                {viewMode === 'signIn' && (
                    <div className="text-right text-sm"><button type="button" onClick={() => setViewMode('forgotPassword')} className="font-medium text-primary hover:text-primary-dark dark:text-primary-light dark:hover:text-primary">{t('recovery.forgot')}</button></div>
                )}
                <button type="submit" disabled={isSubmitting} className="w-full flex justify-center py-3 px-4 border border-transparent rounded-lg shadow-sm text-sm font-medium text-white bg-amber-500 hover:bg-amber-600 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-amber-500 disabled:opacity-50">
                     {isSubmitting ? <LoadingSpinner /> : (viewMode === 'signUp' ? t('auth.signUp') : t('auth.signIn'))}
                </button>
                {errors.general && <p className="text-red-500 text-sm mt-2 text-center">{errors.general}</p>}
            </form>

            <div className="text-sm text-center">
                {viewMode === 'signUp' ? t('auth.alreadyAccount') : t('auth.needAnAccount')}{' '}
                <button onClick={() => { setViewMode(viewMode === 'signUp' ? 'signIn' : 'signUp'); setErrors({}); setMessage(''); }} className="font-medium text-primary hover:text-primary-dark dark:text-primary-light dark:hover:text-primary">
                  {viewMode === 'signUp' ? t('auth.signIn') : t('auth.signUpWithEmail')}
                </button>
            </div>
        </div>
    );
  }

  return (
    <div className="min-h-screen bg-white dark:bg-gray-900 text-gray-900 dark:text-gray-100 flex items-center justify-center p-4">
      <div className="max-w-md w-full">
        {renderContent()}
      </div>
    </div>
  );
};

export default SignUp;

import { GoogleGenAI, HarmCategory, HarmBlockThreshold, GenerateContentResponse, Type } from "@google/genai";
import type { UserDetails, Lecture, StudyGoal, AgendaItem, SmartPlan, ImagePart, QuizQuestion, QuizType, ChatTurn } from '../types';

// ============================================
// CORE CONFIGURATION
// ============================================

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY! });

const safetySettings = [
    { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_NONE },
    { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_NONE },
    { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_NONE },
    { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_NONE },
];

// Fast model for all operations
const MODEL = 'gemini-2.0-flash-exp';

// ============================================
// SIMPLIFIED CACHE
// ============================================

class FastCache {
    private cache = new Map<string, any>();
    private readonly MAX_SIZE = 50;

    get(key: string): any | null {
        return this.cache.get(key) ?? null;
    }

    set(key: string, data: any): void {
        if (this.cache.size >= this.MAX_SIZE) {
            const first = this.cache.keys().next().value;
            this.cache.delete(first);
        }
        this.cache.set(key, data);
    }

    clear(): void {
        this.cache.clear();
    }
}

const cache = new FastCache();

// ============================================
// OPTIMIZED SCHEMAS
// ============================================

const planSlotSchema = {
    type: Type.OBJECT,
    properties: {
        activity: { type: Type.STRING },
        startTime: { type: Type.STRING },
        endTime: { type: Type.STRING },
        type: { type: Type.STRING }, // 'lecture', 'break', 'free'
        code: { type: Type.STRING },
        location: { type: Type.STRING },
        durationMinutes: { type: Type.NUMBER },
    },
    required: ['activity', 'startTime', 'endTime', 'type']
};

const smartPlanSchema = {
    type: Type.ARRAY,
    items: {
        type: Type.OBJECT,
        properties: {
            day: { type: Type.STRING },
            slots: { type: Type.ARRAY, items: planSlotSchema }
        },
        required: ['day', 'slots']
    }
};

const quizSchema = {
    type: Type.ARRAY,
    items: {
        type: Type.OBJECT,
        properties: {
            question: { type: Type.STRING },
            options: { type: Type.ARRAY, items: { type: Type.STRING } },
            correctAnswer: { type: Type.STRING },
            explanation: { type: Type.STRING },
            topic: { type: Type.STRING },
            type: { type: Type.STRING },
        },
        required: ['question', 'correctAnswer', 'explanation', 'topic', 'type']
    }
};

const graphSolutionSchema = {
    type: Type.OBJECT,
    properties: {
        explanation: { type: Type.STRING },
        graphFunction: { type: Type.STRING },
        suggestedTitle: { type: Type.STRING },
    },
    required: ['explanation', 'graphFunction']
};

const tableSchema = {
    type: Type.OBJECT,
    properties: {
        title: { type: Type.STRING },
        headers: { type: Type.ARRAY, items: { type: Type.STRING } },
        rows: { type: Type.ARRAY, items: { type: Type.ARRAY, items: { type: Type.STRING } } },
        caption: { type: Type.STRING }
    },
    required: ['headers', 'rows']
};

// ============================================
// FAST PARSER
// ============================================

const parseJSON = <T>(response: GenerateContentResponse, fallback?: T): T => {
    try {
        let text = response.text.trim();

        // Strip markdown if present
        if (text.startsWith('```')) {
            const start = text.indexOf('{') !== -1 ? text.indexOf('{') : text.indexOf('[');
            const end = text.lastIndexOf('}') !== -1 ? text.lastIndexOf('}') : text.lastIndexOf(']');
            if (start !== -1 && end !== -1) {
                text = text.substring(start, end + 1);
            }
        }

        return JSON.parse(text) as T;
    } catch (e) {
        console.error("Parse error:", e);
        if (fallback !== undefined) return fallback;
        throw new Error("Failed to parse AI response");
    }
};

// ============================================
// CLEAN & OPTIMIZE PLAN OUTPUT
// ============================================

const cleanPlan = (plan: SmartPlan): SmartPlan => {
    return plan.map(dayPlan => ({
        ...dayPlan,
        slots: dayPlan.slots.map(slot => {
            let { activity, type, code, location } = slot;

            // Use course codes when available
            if (code && type === 'lecture') {
                activity = code.toUpperCase();
            }

            // Remove redundant words
            activity = activity
                .replace(/\s+(study|session|class|lecture)$/i, '')
                .trim();

            // Lectures can have locations, breaks/free cannot
            if (type !== 'lecture') {
                location = undefined;
            }

            return { ...slot, activity, location };
        })
    }));
};

// ============================================
// SMART PLAN GENERATION (SIMPLIFIED & FAST)
// ============================================

export const generateSmartPlan = async (
    userDetails: UserDetails,
    lectures: Lecture[],
    studyGoals: StudyGoal[], // IGNORED
    agendaItems: AgendaItem[], // IGNORED
    generalGoals: string, // IGNORED
    existingPlan?: SmartPlan
): Promise<SmartPlan> => {
    const cacheKey = `plan_${JSON.stringify(lectures).substring(0, 80)}`;
    const cached = cache.get(cacheKey);
    if (cached) return cached;

    const prompt = `Create a highly INTENSIVE weekly class schedule with many study sessions and breaks in JSON format.

**Input:**
- User: ${userDetails.name} (${userDetails.major || 'student'})
- Lectures: ${JSON.stringify(lectures)}

**CRITICAL REQUIREMENTS (STRICTLY FOLLOW):**
1. **FULL SCHEDULE:** The schedule must cover 8:00 AM to 10:00 PM every day.
2. **ADD ALL LECTURES:** Include all lectures from the input with exact times.
3. **MAXIMIZE STUDY TIME:** Fill EVERY available gap between lectures with 'study' sessions. Do not leave large gaps.
4. **FREQUENT BREAKS:** Insert a short 'break' (15-30 min) after every study block or long lecture.
5. **MINIMIZE FREE TIME:** Only use 'free' for late nights (after 10 PM) or Sunday mornings. The schedule should look busy.
6. **USE COURSE CODES:** Use activity names like "MATH 101" or "PHYS 202" (not "Mathematics Study").

**Slot Types:**
- 'lecture': Classes from input (WITH location)
- 'study': Self-study sessions (NO location)
- 'break': Rest periods (NO location)
- 'free': Unscheduled time (Only late night)

**Format:**
- 7 days (Monday-Sunday)
- Times in "HH:MM AM/PM" format

Return ONLY the JSON array.`;

    const response = await ai.models.generateContent({
        model: MODEL,
        contents: prompt,
        config: {
            responseMimeType: 'application/json',
            responseSchema: smartPlanSchema,
            temperature: 0.2,
            safetySettings,
        },
    });

    const plan = parseJSON<SmartPlan>(response, []);
    const cleaned = cleanPlan(plan);

    cache.set(cacheKey, cleaned);
    return cleaned;
};

// ============================================
// IMAGE-BASED PLAN (SIMPLIFIED & FAST)
