export const generatePlanFromImage = async (
    userDetails: UserDetails,
    studyGoals: StudyGoal[], // IGNORED
    agendaItems: AgendaItem[], // IGNORED
    generalGoals: string, // IGNORED
    image: ImagePart,
    existingPlan?: SmartPlan
): Promise<SmartPlan> => {
    const prompt = `Extract class schedule from this timetable image and create an INTENSIVE weekly plan in JSON.

**Instructions:**
1. **Find all classes/lectures** - extract course codes, times, locations
2. **FILL GAPS WITH STUDY:** Fill empty time blocks between classes with 'study' sessions.
3. **ADD BREAKS:** Insert short 'break' slots (15-30 mins) frequently.
4. **MINIMIZE FREE TIME:** The user wants a busy schedule. Limit 'free' time to late nights.
5. **Use exact course codes** from image (e.g., "BIO 304", "STAT 243")

**Slot Types:**
- 'lecture': Classes from timetable (WITH location)
- 'study': Self-study blocks
- 'break': Rest periods
- 'free': Only for late night

**Format:**
- 7 days, "HH:MM AM/PM" times
- Use course codes as-is from image

Return ONLY JSON array.`;

    const response = await ai.models.generateContent({
        model: MODEL,
        contents: { parts: [{ text: prompt }, image] },
        config: {
            responseMimeType: 'application/json',
            responseSchema: smartPlanSchema,
            temperature: 0.2,
            safetySettings,
        },
    });

    const plan = parseJSON<SmartPlan>(response, []);
    return cleanPlan(plan);
};

