export const isImageTimetable = async (image: ImagePart): Promise<boolean> => {
    const cacheKey = `tt_${image.inlineData.data.substring(0, 40)}`;
    const cached = cache.get(cacheKey);
    if (cached !== null) return cached;

    const response = await ai.models.generateContent({
        model: MODEL,
        contents: { parts: [{ text: "Is this a class timetable/schedule? Answer: true or false" }, image] },
        config: { safetySettings, maxOutputTokens: 5 },
    });

    const result = response.text.trim().toLowerCase().includes('true');
    cache.set(cacheKey, result);
    return result;
};

