// ============================================
// INTERACTIVE CHAT (STREAMING)
// ============================================

export const chatWithDocumentStream = async (
    file: ImagePart | null,
    userMessage: string,
    history: ChatTurn[],
    context: string,
    smartPlan?: SmartPlan | null
) => {
    const chatHistory = history.map(turn => ([
        { role: 'user', parts: [{ text: turn.user }] },
        { role: 'model', parts: [{ text: turn.blay }] }
    ])).flat();

    const systemInstruction = `You are Blay, a helpful AI tutor. Context: ${context}. Use markdown for formatting.`;

    const contents: any = [...chatHistory];
    const userParts: ({ text: string } | ImagePart)[] = [{ text: userMessage }];
    if (file) userParts.push(file);
    contents.push({ role: 'user', parts: userParts });

    return await ai.models.generateContentStream({
        model: MODEL,
        contents,
        config: { systemInstruction, safetySettings },
    });
};

