// ============================================
// FAST PARSER
// ============================================

const parseJSON = <T>(response: GenerateContentResponse, fallback?: T): T => {
    try {
        let text = response.text.trim();

        // Strip markdown if present
        if (text.startsWith('```')) {
            const start = text.indexOf('{') !== -1 ? text.indexOf('{') : text.indexOf('[');
            const end = text.lastIndexOf('}') !== -1 ? text.lastIndexOf('}') : text.lastIndexOf(']');
            if (start !== -1 && end !== -1) {
                text = text.substring(start, end + 1);
            }
        }

        return JSON.parse(text) as T;
    } catch (e) {
        console.error("Parse error:", e);
        if (fallback !== undefined) return fallback;
        throw new Error("Failed to parse AI response");
    }
};

// ============================================
// CLEAN & OPTIMIZE PLAN OUTPUT
// ============================================

const cleanPlan = (plan: SmartPlan): SmartPlan => {
    return plan.map(dayPlan => ({
        ...dayPlan,
        slots: dayPlan.slots.map(slot => {
            let { activity, type, code, location } = slot;

            // Use course codes when available
            if (code && type === 'lecture') {
                activity = code.toUpperCase();
            }

            // Remove redundant words
            activity = activity
                .replace(/\s+(study|session|class|lecture)$/i, '')
                .trim();

            // Lectures can have locations, breaks/free cannot
            if (type !== 'lecture') {
                location = undefined;
            }

            return { ...slot, activity, location };
        })
    }));
};

