    agendaItems: AgendaItem[], // IGNORED
    generalGoals: string, // IGNORED
    existingPlan?: SmartPlan
): Promise<SmartPlan> => {
    const cacheKey = `plan_${JSON.stringify(lectures).substring(0, 80)}`;
    const cached = cache.get(cacheKey);
    if (cached) return cached;

    const prompt = `Create a highly INTENSIVE weekly class schedule with many study sessions and breaks in JSON format.

**Input:**
- User: ${userDetails.name} (${userDetails.programmeOfStudy || 'student'})
- Lectures: ${JSON.stringify(lectures)}

**CRITICAL REQUIREMENTS (STRICTLY FOLLOW):**
1. **FULL SCHEDULE:** The schedule must cover 8:00 AM to 10:00 PM every day.
2. **ADD ALL LECTURES:** Include all lectures from the input with exact times.
3. **MAXIMIZE STUDY TIME:** Fill EVERY available gap between lectures with 'study' sessions. Do not leave large gaps.
4. **FREQUENT BREAKS:** Insert a short 'break' (15-30 min) after every study block or long lecture.
5. **MINIMIZE FREE TIME:** Only use 'free' for late nights (after 10 PM) or Sunday mornings. The schedule should look busy.
6. **USE COURSE CODES:** Use activity names like "MATH 101" or "PHYS 202" (not "Mathematics Study").

**Slot Types:**
- 'lecture': Classes from input (WITH location)
- 'study': Self-study sessions (NO location)
- 'break': Rest periods (NO location)
- 'free': Unscheduled time (Only late night)

**Format:**
- 7 days (Monday-Sunday)
- Times in "HH:MM AM/PM" format

Return ONLY the JSON array.`;

    const response = await ai.models.generateContent({
        model: MODEL,
        contents: prompt,
        config: {
            responseMimeType: 'application/json',
            responseSchema: smartPlanSchema,
            temperature: 0.2,
            safetySettings,
        },
    });

    const plan = parseJSON<SmartPlan>(response, []);
    const cleaned = cleanPlan(plan);

    cache.set(cacheKey, cleaned);
    return cleaned;
};

