// ============================================
// FIX 1: NotificationSettings Component (Mobile-Optimized)
// ============================================

import React, { useState, useEffect } from 'react';
import type { NotificationSettings } from '../types';
import { useLanguage } from '../contexts/LanguageContext';
import { notificationService } from '../services/notificationService';
import { VolumeIcon } from './icons/VolumeIcon';

interface NotificationSettingsProps {
    settings: NotificationSettings;
    setSettings: (settings: NotificationSettings) => void;
}

const NotificationSettingsComponent: React.FC<NotificationSettingsProps> = ({ settings, setSettings }) => {
    const { t } = useLanguage();
    const [isCustomTime, setIsCustomTime] = useState(false);
    const [permissionStatus, setPermissionStatus] = useState<NotificationPermission | 'unsupported'>('default');
    const [isSupported, setIsSupported] = useState(true);
    const [isChecking, setIsChecking] = useState(true);

    // Safely check notification support and status
    useEffect(() => {
        const checkSupport = () => {
            try {
                // More robust check for mobile browsers
                if (typeof window === 'undefined' || 
                    typeof Notification === 'undefined' || 
                    !('Notification' in window)) {
                    setIsSupported(false);
                    setPermissionStatus('unsupported');
                    setIsChecking(false);
                    return;
                }

                setPermissionStatus(Notification.permission);
                setIsSupported(true);
            } catch (e) {
                console.error("Error accessing Notification API:", e);
                setIsSupported(false);
                setPermissionStatus('unsupported');
            } finally {
                setIsChecking(false);
            }
        };

        checkSupport();

        // Poll for permission changes (mobile browsers may not fire events)
        const interval = setInterval(() => {
            if (typeof Notification !== 'undefined' && Notification.permission) {
                setPermissionStatus(Notification.permission);
            }
        }, 2000);

        return () => clearInterval(interval);
    }, []);

    useEffect(() => {
        if (![5, 10, 15].includes(settings.reminderTime)) {
            setIsCustomTime(true);
        } else {
            setIsCustomTime(false);
        }
    }, [settings.reminderTime]);

    const handleRequestPermission = async () => {
        if (!isSupported) {
            alert('Notifications are not supported on this device.');
            return;
        }

        try {
            // Mobile-friendly permission request
            const permission = await Notification.requestPermission();
            setPermissionStatus(permission);

            if (permission === 'granted') {
                setSettings({
                    ...settings,
                    enabled: true,
                    status: 'configured',
                    reminders: true,
                    sessionStart: true,
                    breakStartEnd: true
                });

                // Test notification
                try {
                    new Notification('EduBlay Notifications Enabled! 🔔', {
                        body: 'You will now receive study reminders.',
                        icon: '/favicon.ico'
                    });
                } catch (e) {
                    console.warn('Could not show test notification:', e);
                }
            }
        } catch (error) {
            console.error('Error requesting permission:', error);
            alert('Failed to request notification permission. Please enable manually in browser settings.');
        }
    };

    const updateSetting = <K extends keyof NotificationSettings>(key: K, value: NotificationSettings[K]) => {
        setSettings({ ...settings, [key]: value });
    };

    const handleMasterSwitchChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const isEnabled = e.target.checked;

        if (isEnabled) {
            if (!isSupported) {
                alert('Notifications are not supported by this browser/device.');
                return;
            }

            if (Notification.permission === 'granted') {
                setSettings({
                    ...settings,
                    enabled: true,
                    status: 'configured'
                });
            } else if (Notification.permission === 'denied') {
                setSettings({
                    ...settings,
                    enabled: true,
                    status: 'configured'
                });
            } else {
                // Request permission immediately on mobile
                await handleRequestPermission();
            }
        } else {
            updateSetting('enabled', false);
        }
    };

    const handleReminderTimeSelect = (e: React.ChangeEvent<HTMLSelectElement>) => {
        const value = e.target.value;
        if (value === 'custom') {
            setIsCustomTime(true);
        } else {
            setIsCustomTime(false);
            updateSetting('reminderTime', parseInt(value, 10));
        }
    };

    const baseInputClasses = "block w-full px-3 py-2.5 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm placeholder-gray-400 text-gray-900 dark:text-gray-200 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-base";

    // Loading state
    if (isChecking) {
        return (
            <div className="max-w-2xl mx-auto">
                <h2 className="text-2xl sm:text-3xl font-bold text-gray-800 dark:text-white mb-6">
                    {t('preferences.notifications.title') || 'Notifications'}
                </h2>
                <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg p-6 border dark:border-gray-700">
                    <div className="flex items-center justify-center p-8">
                        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
                        <span className="ml-3 text-gray-600 dark:text-gray-400">Checking notification support...</span>
                    </div>
                </div>
            </div>
        );
    }

    if (!isSupported) {
        return (
            <div className="max-w-2xl mx-auto px-4">
                <h2 className="text-2xl sm:text-3xl font-bold text-gray-800 dark:text-white mb-6">
                    {t('preferences.notifications.title') || 'Notifications'}
                </h2>
                <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg p-6 border dark:border-gray-700">
                    <div className="p-4 bg-yellow-50 dark:bg-yellow-900/20 rounded-lg text-center">
                        <p className="text-yellow-800 dark:text-yellow-200 font-medium text-base">
                            Notifications are not supported on this browser or device.
                        </p>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="max-w-2xl mx-auto px-4">
            <div>
                <h2 className="text-2xl sm:text-3xl font-bold text-gray-800 dark:text-white mb-6">
                    {t('preferences.notifications.title') || 'Notifications'}
                </h2>
            </div>

            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg p-4 sm:p-6 border dark:border-gray-700 transition-all duration-300">
                <div className="space-y-6">
                    {/* Master Switch */}
                    <div className="flex items-center justify-between pb-4 border-b dark:border-gray-700">
                        <div className="flex-1 pr-4">
                            <label htmlFor="master-switch" className="font-semibold text-base sm:text-lg cursor-pointer block">
                                {t('notifications.enable') || 'Enable Notifications'}
                            </label>
                            {settings.enabled && (
                                <p className={`text-sm mt-1 flex items-center gap-1 ${
                                    permissionStatus === 'granted' ? 'text-green-600 dark:text-green-400' : 
                                    permissionStatus === 'denied' ? 'text-red-600 dark:text-red-400' : 
                                    'text-yellow-600 dark:text-yellow-400'
                                }`}>
                                    {permissionStatus === 'granted' ? '✓ Active' : 
                                     permissionStatus === 'denied' ? '✗ Blocked' : 
                                     '⚠ Permission Needed'}
                                </p>
                            )}
                        </div>
                        <input 
                            id="master-switch" 
                            type="checkbox" 
                            checked={settings.enabled} 
                            onChange={handleMasterSwitchChange} 
                            className="h-7 w-12 rounded-full bg-gray-300 dark:bg-gray-600 appearance-none checked:bg-blue-600 transition duration-200 ease-in-out relative cursor-pointer
                            after:content-[''] after:h-6 after:w-6 after:rounded-full after:bg-white after:absolute after:top-0.5 after:left-0.5 after:transition after:duration-200 checked:after:translate-x-5" 
                        />
                    </div>

                    {/* Notification Options */}
                    {settings.enabled && (
                        <div className="space-y-6 pt-2">

                            {/* Warning banner for denied permission */}
                            {permissionStatus === 'denied' && (
                                <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-4">
                                    <div className="flex gap-3">
                                        <div className="text-2xl flex-shrink-0">🔒</div>
                                        <div className="flex-1 min-w-0">
                                            <h4 className="font-semibold text-red-900 dark:text-red-200 mb-2 text-base">
                                                Notifications Blocked
                                            </h4>
                                            <p className="text-sm text-red-800 dark:text-red-300 mb-3">
                                                You previously blocked notifications. To enable:
                                            </p>
                                            <ol className="text-sm text-red-800 dark:text-red-300 space-y-1.5 list-decimal list-inside">
                                                <li>Tap the <strong>lock icon (🔒)</strong> in your address bar</li>
                                                <li>Find <strong>"Notifications"</strong></li>
                                                <li>Change to <strong>"Allow"</strong></li>
                                                <li>Reload this page</li>
                                            </ol>
                                        </div>
                                    </div>
                                </div>
                            )}

                            {/* Prompt banner for default permission */}
                            {permissionStatus === 'default' && (
                                <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg p-4 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3">
                                    <p className="text-sm text-blue-800 dark:text-blue-300">
                                        Browser permission required to receive notifications.
                                    </p>
                                    <button 
                                        onClick={handleRequestPermission}
                                        className="px-4 py-2 text-sm font-semibold bg-blue-600 text-white rounded-md hover:bg-blue-700 active:bg-blue-800 whitespace-nowrap w-full sm:w-auto"
                                    >
                                        Allow Notifications
                                    </button>
                                </div>
                            )}

                            {/* Test Sound Button */}
                            <div className="flex justify-end">
                                <button 
                                    onClick={() => notificationService.testAlarm()}
                                    className="flex items-center gap-2 px-4 py-2.5 text-sm font-medium text-gray-700 dark:text-gray-200 bg-gray-100 dark:bg-gray-700 rounded-md hover:bg-gray-200 dark:hover:bg-gray-600 active:bg-gray-300 dark:active:bg-gray-500 transition-colors border border-gray-300 dark:border-gray-600 shadow-sm"
                                >
                                    <VolumeIcon className="w-4 h-4" />
                                    <span>Test Sound</span>
                                </button>
                            </div>

                            {/* Pre-session reminders */}
                            <div className="flex items-start justify-between p-4 bg-gray-50 dark:bg-gray-700/50 rounded-lg gap-4">
                                <div className="flex-1 min-w-0">
                                    <label htmlFor="reminders" className="font-medium cursor-pointer text-base block">
                                        {t('notifications.reminders') || 'Pre-session reminders'}
                                    </label>
                                    <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
                                        {t('notifications.remindersDesc') || 'Get notified before sessions start.'}
                                    </p>
                                </div>
                                <input 
                                    id="reminders" 
                                    type="checkbox" 
                                    checked={settings.reminders} 
                                    onChange={e => updateSetting('reminders', e.target.checked)} 
                                    className="h-5 w-5 rounded mt-1 text-blue-600 focus:ring-2 focus:ring-blue-500 shrink-0 cursor-pointer" 
                                />
                            </div>

                            {/* Reminder Time Selector */}
                            {settings.reminders && (
                                <div className="pl-4 sm:pl-6 space-y-3 border-l-2 border-blue-500 ml-1">
                                    <label htmlFor="reminderTime" className="text-sm font-medium block">
                                        {t('notifications.remindMeBefore') || 'Remind me before'}
                                    </label>
                                    <div className="flex gap-2 flex-col sm:flex-row">
                                        <select 
                                            id="reminderTime" 
                                            value={isCustomTime ? 'custom' : settings.reminderTime} 
                                            onChange={handleReminderTimeSelect} 
                                            className={`${baseInputClasses} flex-1`}
                                        >
                                            <option value={5}>5 minutes</option>
                                            <option value={10}>10 minutes</option>
                                            <option value={15}>15 minutes</option>
                                            <option value="custom">Custom</option>
                                        </select>
                                        {isCustomTime && (
                                            <input 
                                                type="number" 
                                                value={settings.reminderTime} 
                                                onChange={e => updateSetting('reminderTime', parseInt(e.target.value, 10) || 5)} 
                                                className={`${baseInputClasses} w-full sm:w-24`}
                                                min="1"
                                                max="60"
                                                placeholder="Minutes"
                                            />
                                        )}
                                    </div>
                                </div>
                            )}

                            {/* Session start alert */}
                            <div className="flex items-start justify-between p-4 bg-gray-50 dark:bg-gray-700/50 rounded-lg gap-4">
                                <div className="flex-1 min-w-0">
                                    <label htmlFor="sessionStart" className="font-medium cursor-pointer text-base block">
                                        {t('notifications.sessionStart') || 'Session start alert'}
                                    </label>
                                    <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
                                        {t('notifications.sessionStartDesc') || 'Alert when sessions begin.'}
                                    </p>
                                </div>
                                <input 
                                    id="sessionStart" 
                                    type="checkbox" 
                                    checked={settings.sessionStart} 
                                    onChange={e => updateSetting('sessionStart', e.target.checked)} 
                                    className="h-5 w-5 rounded mt-1 text-blue-600 focus:ring-2 focus:ring-blue-500 shrink-0 cursor-pointer" 
                                />
                            </div>

                            {/* Break alerts */}
                            <div className="flex items-start justify-between p-4 bg-gray-50 dark:bg-gray-700/50 rounded-lg gap-4">
                                <div className="flex-1 min-w-0">
                                    <label htmlFor="breakAlerts" className="font-medium cursor-pointer text-base block">
                                        {t('notifications.breakAlerts') || 'Break alerts'}
                                    </label>
                                    <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
                                        {t('notifications.breakAlertsDesc') || 'Notifications for break times.'}
                                    </p>
                                </div>
                                <input 
                                    id="breakAlerts" 
                                    type="checkbox" 
                                    checked={settings.breakStartEnd} 
                                    onChange={e => updateSetting('breakStartEnd', e.target.checked)} 
                                    className="h-5 w-5 rounded mt-1 text-blue-600 focus:ring-2 focus:ring-blue-500 shrink-0 cursor-pointer" 
                                />
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default NotificationSettingsComponent;



