export const generateSmartPlan = async (
    userDetails: UserDetails,
    lectures: Lecture[],
    studyGoals: StudyGoal[], 
    agendaItems: AgendaItem[],
    generalGoals: string,
    existingPlan?: SmartPlan
): Promise<SmartPlan> => {
    const cacheKey = `plan_${JSON.stringify({ lectures, studyGoals, agendaItems }).substring(0, 100)}`;
    const cached = cache.get(cacheKey);
    if (cached) return cached;

    const prompt = `Create a highly INTENSIVE weekly class schedule in JSON format.

**Input Data:**
- User: ${userDetails.name} (${userDetails.programmeOfStudy || 'student'})
- Lectures (Fixed): ${JSON.stringify(lectures)}
- Personal Agenda (Fixed): ${JSON.stringify(agendaItems)}
- Study Goals: ${JSON.stringify(studyGoals)}
- General Goals: ${generalGoals}

**CRITICAL INSTRUCTIONS (STRICTLY FOLLOW):**
1.  **NO HALLUCINATIONS:** Do NOT invent course codes. If the input subject is "Biology", label the activity "Biology". Only use a code like "BIO 101" if it was explicitly provided in the input.
2.  **FIXED EVENTS:** You MUST schedule all 'Lectures' and 'Personal Agenda' items exactly at their specified times. These are locked.
3.  **FILL GAPS:** Fill gaps between fixed events with 'study' sessions based on the Study Goals.
4.  **BREAKS:** Insert short 'break' slots (15-30 mins) after long blocks.
5.  **TYPES:** 
    - Use 'lecture' for input lectures.
    - Use 'agenda' for personal agenda items.
    - Use 'study' for study sessions.
    - Use 'break' for rest.
    - Use 'free' for unscheduled time (late nights/weekends).

**Format:**
- 7 days (Monday-Sunday)
- Times in "HH:MM AM/PM" format

Return ONLY the JSON array.`;

    const response = await ai.models.generateContent({
        model: MODEL,
        contents: prompt,
        config: {
            responseMimeType: 'application/json',
            responseSchema: smartPlanSchema,
            temperature: 0.2,
            safetySettings,
        },
    });

    const plan = parseJSON<SmartPlan>(response, []);
    const cleaned = cleanPlan(plan);

    cache.set(cacheKey, cleaned);
    return cleaned;
};

