export const generateSmartPlan = async (
    userDetails: UserDetails,
    lectures: Lecture[],
    studyGoals: StudyGoal[], 
    agendaItems: AgendaItem[],
    generalGoals: string,
    existingPlan?: SmartPlan
): Promise<SmartPlan> => {
    const cacheKey = `plan_${JSON.stringify({ lectures, studyGoals, agendaItems }).substring(0, 100)}`;
    const cached = cache.get(cacheKey);
    if (cached) return cached;

    // Create a strict allowed list of subjects from the inputs
    const allowedSubjects = [
        ...lectures.map(l => l.subject),
        ...studyGoals.map(s => s.subject)
    ].filter(Boolean).join(", ");

    const prompt = `Create a weekly class schedule in JSON format.

**STRICT DATA SOURCES (DO NOT DEVIATE):**
1. **Lectures (FIXED):** ${JSON.stringify(lectures)}
2. **Personal Agenda (FIXED):** ${JSON.stringify(agendaItems)}
3. **Allowed Study Topics:** ${allowedSubjects || "General Revision"}

**CRITICAL RULES:**
1. **NO HALLUCINATIONS:** You are STRICTLY FORBIDDEN from inventing new courses or course codes. 
   - If the user input is "Math", the study session must be "Math". Do NOT write "MAT 101".
   - If the user input is "Biology", use "Biology". Do NOT write "BIO 120".
   - ONLY use a course code (e.g., "CS 101") if it explicitly appears in the 'Lectures' list above.
2. **STUDY SESSIONS:** Fill gaps with 'study' sessions. The 'activity' name for these sessions MUST be one of the **Allowed Study Topics** listed above. Do not create random subjects.
3. **FIXED EVENTS:** Schedule 'lecture' and 'agenda' items exactly at their provided times.
4. **BREAKS:** Insert short 'break' slots (15-30 mins).

**Format:**
- 7 days (Monday-Sunday)
- Times in "HH:MM AM/PM" format

Return ONLY the JSON array.`;

    const response = await ai.models.generateContent({
        model: MODEL,
        contents: prompt,
        config: {
            responseMimeType: 'application/json',
            responseSchema: smartPlanSchema,
            temperature: 0.1, // Lower temperature for stricter adherence
            safetySettings,
        },
    });

    const plan = parseJSON<SmartPlan>(response, []);
    const cleaned = cleanPlan(plan);

    cache.set(cacheKey, cleaned);
    return cleaned;
};

