                                    'text-yellow-600 dark:text-yellow-400'
                                }`}>
                                    {permissionStatus === 'granted' ? 'Active' : 
                                     permissionStatus === 'denied' ? 'Blocked by Browser' : 
                                     'Permission Needed'}
                                </p>
                            )}
                        </div>
                        <input 
                            id="master-switch" 
                            type="checkbox" 
                            checked={settings.enabled} 
                            onChange={handleMasterSwitchChange} 
                            className="h-6 w-11 rounded-full bg-gray-300 dark:bg-gray-600 appearance-none checked:bg-blue-600 transition duration-200 ease-in-out relative cursor-pointer
                            after:content-[''] after:h-5 after:w-5 after:rounded-full after:bg-white after:absolute after:top-0.5 after:left-0.5 after:transition after:duration-200 checked:after:translate-x-5" 
                        />
                    </div>

                    {/* Notification Options */}
                    {settings.enabled && (
                        <div className="space-y-6 pt-2 animate-fade-in-down origin-top">

                            {/* Warning banner ONLY if permission is actively denied */}
                            {permissionStatus === 'denied' && (
