  const [uploadedMaterials, setUploadedMaterials] = useState<UploadedMaterialInfo[]>([]);
  const [generationState, setGenerationState] = useState<GenerationState>({ isLoading: false, message: '', error: null, source: 'dashboard' });
  const [quizState, setQuizState] = useState<QuizState>(defaultQuizState);
  const [intendedStudyContext, setIntendedStudyContext] = useState<{ subject: string; fromSlot: PlanSlot } | null>(null);
  const [tutorialVideoUrl] = useState<string>('https://youtu.be/f14AwLpLb9E');
  const [welcomeComplete, setWelcomeComplete] = useState(() => storageService.loadItem<boolean>('welcomeComplete') || false);
  const [courseCodeMap, setCourseCodeMap] = useState<CourseCodeMap>({});

  // Collaborative Session State
  const [activeCode, setActiveCode] = useState<string | null>(null);


  // Persistent component states
  const [dashboardInputs, setDashboardInputs] = useState<DashboardInputState>({ lectures: [], studyGoals: [], agendaItems: [], generalGoals: '', imageFile: null, imagePreview: null, step: 1, isManualPlan: false, isEditing: false });
  const [examPrepState, setExamPrepState] = useState<ExamPrepState>({ mode: 'quiz', topic: '', numQuestions: 5, quizType: QuizType.MCQ, uploadedFiles: [], focusArea: '', isVerifying: false, questionImage: null, questionText: '', solution: null, outputFormat: 'steps', programmingLanguage: 'python', graphInterval: '', graphYInterval: '', graphConfig: null });
  const [profileEditState, setProfileEditState] = useState<ProfileEditState>({ isEditing: false, details: null });
  const [notesViewState, setNotesViewState] = useState<NotesViewState>({ currentNoteId: null, searchTerm: '' });
  const [reportDraft, setReportDraft] = useState<ReportDraft>({ category: 'bug', description: '', attachment: null, contactEmail: '', contactWhatsApp: '' });

  const [showNotifPrompt, setShowNotifPrompt] = useState(false);

  const addToast = useCallback((message: string, type: Toast['type']) => {
    const newToast = { id: Date.now(), message, type };
    setToasts(prev => [...prev, newToast]);
  }, []);

  const persistAllState = useCallback(() => {
    if (!userDetails?.email) return;

    // Use specific user ID if available, otherwise email is a unique enough key for this context if ID is missing.
    // Ideally userDetails.id comes from authService.login/signup
    const userId = userDetails.id || userDetails.email;

    const currentUserData = {
        userDetails,
        smartPlan,
        savedTimetables,
        notes,
        notificationSettings,
        trackedData,
        uploadedMaterials,
        courseCodeMap,
        quizState: {
            quiz: quizState.quiz,
            currentQuestionIndex: quizState.currentQuestionIndex,
            userAnswers: quizState.userAnswers,
        },
        // PERSIST HUB AND DASHBOARD STATE
        learningHubState: {
            ...learningHubState,
            isProcessing: false // Never persist loading state
        },
        dashboardInputs: {
            ...dashboardInputs,
            imageFile: null // Don't persist File objects (non-serializable), rely on imagePreview data URL
        }
    };

    // Save locally
    const allUsersData = storageService.loadItem<any>('usersData') || {};
    allUsersData[userDetails.email] = currentUserData;
    storageService.saveItem('usersData', allUsersData);

    // Sync to Cloud
    storageService.syncUserToCloud(userId, currentUserData);

  }, [userDetails, smartPlan, savedTimetables, notes, notificationSettings, trackedData, quizState, uploadedMaterials, courseCodeMap, learningHubState, dashboardInputs]);

    const loadUserData = useCallback((user: UserDetails) => {
        // Try to load from Local Storage first for speed
        const allUsersData = storageService.loadItem<any>('usersData') || {};
        let userData = allUsersData[user.email!];

        // Legacy cleanup (migration from old single-user structure)
        if (!userData) {
            const legacySmartPlan = storageService.loadItem('smartPlan');
            if (legacySmartPlan) {
                userData = {};
                userData.smartPlan = legacySmartPlan;
                userData.savedTimetables = storageService.loadItem('savedTimetables');
                userData.notes = storageService.loadItem('notes');
                userData.trackedData = storageService.loadItem('trackedData');
                userData.notificationSettings = storageService.loadItem('notificationSettings');
                userData.quizProgress = storageService.loadItem('quizProgress');
                userData.userDetails = storageService.loadItem('userDetails');
                userData.courseCodeMap = {}; 
                // Cleanup old keys
                ['smartPlan', 'savedTimetables', 'notes', 'trackedData', 'notificationSettings', 'quizProgress', 'userDetails'].forEach(key => storageService.removeItem(key));
            }
        }

        // Helper to apply state
        const applyState = (data: any) => {
            const finalUserDetails = { ...user, ...(data.userDetails || {}), usage: (data.userDetails?.usage || user.usage || initializeUsage()) };
            setUserDetails(finalUserDetails);
            setSmartPlan(data.smartPlan || null);
            setSavedTimetables(data.savedTimetables || []);
            setNotes(data.notes || []);
            setTrackedData(data.trackedData || []);
            setUploadedMaterials(data.uploadedMaterials || []);
            setNotificationSettings(data.notificationSettings || defaultNotificationSettings);
            setCourseCodeMap(data.courseCodeMap || {});

            if (data.quizState && data.quizState.quiz?.length > 0) {
                setQuizState({ ...defaultQuizState, ...data.quizState, feedback: null, summary: null });
            } else {
                setQuizState(defaultQuizState);
            }

            // Restore Persistent Hub State
            if (data.learningHubState) {
                setLearningHubState(prev => ({
                    ...prev,
                    ...data.learningHubState,
                    isProcessing: false // Ensure we don't start in a loading state
                }));
            }

            // Restore Persistent Dashboard Inputs
            if (data.dashboardInputs) {
                setDashboardInputs(prev => ({
                    ...prev,
                    ...data.dashboardInputs,
                    imageFile: null // File object cannot be restored, but imagePreview (data URL) should be there
                }));
            }
        };

        if (userData) {
            applyState(userData);
        } else {
            // New login on this device? Check cloud data
            // (Note: The login function in authService usually pre-populates localStorage from cloud, 
            // but we check here just in case)
            applyState({}); 
        }

    }, []);

    useEffect(() => {
        const user = getCurrentUser();
        if (user) {
            loadUserData(user);
            setIsLoggedIn(true);
        }
    }, [loadUserData]);

  useEffect(() => {
    const handler = setTimeout(() => {
      if (isLoggedIn) {
        persistAllState();
      }
    }, 2000); // Debounce save to 2 seconds to reduce Firestore writes
    return () => clearTimeout(handler);
  }, [isLoggedIn, persistAllState]);

  // Safe check for Notification prompt in useEffect to prevent render crashes
  useEffect(() => {
    try {
        const shouldShow = notificationSettings.status === 'unconfigured' && 
                            typeof Notification !== 'undefined' && 
                            Notification.permission === 'default';
        setShowNotifPrompt(shouldShow);
    } catch (e) {
