const UploadSlides: React.FC<UploadSlidesProps> = ({
  smartPlan, setSmartPlan, activeSession, setActiveSession, setView, addToast,
  learningHubState, setLearningHubState, notes, setNotes,
  showTitle = true, isStudyModeView = false,
  intendedStudyContext, setIntendedStudyContext,
  onAttemptUpload,
}) => {
  const { t } = useLanguage();
  const [chatInput, setChatInput] = useState('');

  const [readAloudState, setReadAloudState] = useState<ReadAloudState>('idle');
  const [controlsPosition, setControlsPosition] = useState({ x: 0, y: 0 });
  const [readingSpeed, setReadingSpeed] = useState(1);
  const [readingVolume, setReadingVolume] = useState(1);
  const [zoom, setZoom] = useState(1.0);
  const [isHoveringTopBar, setIsHoveringTopBar] = useState(false);
  const [isHoveringPlaybackControls, setIsHoveringPlaybackControls] = useState(false);
  const [highlightCharIndex, setHighlightCharIndex] = useState(-1);

  const utteranceRef = useRef<SpeechSynthesisUtterance | null>(null);
  const speechCharIndexRef = useRef(0);

  const [sessionPrompt, setSessionPrompt] = useState<{ slot: PlanSlot, nextSlot: PlanSlot | null, day: DayOfWeek } | null>(null);
  const [conflictInfo, setConflictInfo] = useState<{ plannedSubject: string; uploadedSubject: string; day: DayOfWeek; slot: PlanSlot; file: UploadedFile; } | null>(null);
  const [showConflictResolution, setShowConflictResolution] = useState(false);
  const [customizationRequest, setCustomizationRequest] = useState<{ file: UploadedFile, slot?: PlanSlot, isUntracked: boolean } | null>(null);
  const [editingMessage, setEditingMessage] = useState<{ index: number; text: string } | null>(null);

  const { file, analysisMode, analysisResults, chatHistory, isProcessing, processingMessage } = learningHubState;

  const setFile = (file: UploadedFile | null) => setLearningHubState(prev => ({ ...prev, file }));
  const setAnalysisMode = (mode: AnalysisMode) => setLearningHubState(prev => ({ ...prev, analysisMode: mode }));
  const setAnalysisResult = (type: 'summarize' | 'explain' | 'read', result: string | null) => {
    setLearningHubState(prev => ({
        ...prev,
        analysisResults: { ...prev.analysisResults, [type]: result }
    }));
  };

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (isHoveringPlaybackControls) return;
    const rect = e.currentTarget.getBoundingClientRect();
    setControlsPosition({
        x: e.clientX - rect.left,
        y: e.clientY - rect.top,
    });
  };

  const handlePlay = useCallback((startIndex = 0) => {
    const textToRead = analysisResults.read;
    if (textToRead && textToRead.length > startIndex) {
        if (speechSynthesis.speaking) {
            speechSynthesis.cancel();
        }
        const utterance = new SpeechSynthesisUtterance(textToRead.substring(startIndex));
        utteranceRef.current = utterance;

        utterance.rate = readingSpeed;
        utterance.volume = readingVolume;

        utterance.onboundary = (event) => {
            const absoluteCharIndex = startIndex + event.charIndex;
            setHighlightCharIndex(absoluteCharIndex);
            speechCharIndexRef.current = absoluteCharIndex;
        };

        utterance.onend = () => {
            if (utteranceRef.current === utterance) {
                setReadAloudState('interactive');
                speechCharIndexRef.current = 0;
                setHighlightCharIndex(-1);
            }
        };

        speechSynthesis.speak(utterance);
        setReadAloudState('playing');
    }
}, [analysisResults.read, readingSpeed, readingVolume]);


  const handleResume = useCallback(() => {
      if (speechSynthesis.paused) {
        speechSynthesis.resume();
        setReadAloudState('playing');
      }
  }, []);

  const handlePause = useCallback(() => {
      if (speechSynthesis.speaking) {
        speechSynthesis.pause();
        setReadAloudState('paused');
      }
  }, []);

  const handleStop = useCallback(() => {
      if (speechSynthesis.speaking || speechSynthesis.paused) {
        utteranceRef.current = null;
        speechSynthesis.cancel();
      }
      setReadAloudState('interactive');
      speechCharIndexRef.current = 0;
      setHighlightCharIndex(-1);
  }, []);

  useEffect(() => {
    if (readAloudState === 'playing') {
        handlePlay(speechCharIndexRef.current);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [readingSpeed, readingVolume]);

  useEffect(() => {
    return () => handleStop();
  }, [file, handleStop]);

  useEffect(() => {
    return () => {
        if (intendedStudyContext) {
            setIntendedStudyContext(null);
        }
    };
  }, [intendedStudyContext, setIntendedStudyContext]);

  const findCurrentSlots = (plan: SmartPlan | null): { slot: PlanSlot | null, nextSlot: PlanSlot | null, day: DayOfWeek | null } => {
    if (!plan) return { slot: null, nextSlot: null, day: null };
    const now = new Date();
    const currentDay = DAYS_OF_WEEK[now.getDay() === 0 ? 6 : now.getDay() - 1];
    const dayPlan = plan.find(d => d.day === currentDay);
    if (!dayPlan) return { slot: null, nextSlot: null, day: currentDay };

    const nowMinutes = now.getHours() * 60 + now.getMinutes();
    const currentSlotIndex = dayPlan.slots.findIndex(slot => 
        timeToMinutes(slot.startTime) <= nowMinutes && 
        timeToMinutes(slot.endTime) > nowMinutes
    );

    if (currentSlotIndex === -1) {
        return { slot: null, nextSlot: null, day: currentDay };
    }

    const slot = dayPlan.slots[currentSlotIndex];
    const nextSlot = currentSlotIndex + 1 < dayPlan.slots.length ? dayPlan.slots[currentSlotIndex + 1] : null;

    return { slot, nextSlot, day: currentDay };
  };


  const onDrop = useCallback((acceptedFiles: File[]) => {
    const droppedFile = acceptedFiles[0];
    if (!droppedFile) return;

    if (droppedFile.size > 25 * 1024 * 1024) { // 25MB limit
        addToast(t('toasts.fileSizeTooLarge', { fileName: droppedFile.name, size: 25 }), 'error');
        return;
    }

    onAttemptUpload(droppedFile);

  }, [addToast, t, onAttemptUpload]);

  const handleStartStudyRequest = () => {
    if (!file) return;

    if (intendedStudyContext) {
        setCustomizationRequest({ file, slot: intendedStudyContext.fromSlot, isUntracked: false });
        setIntendedStudyContext(null);
        return;
    }

    const { slot, nextSlot, day } = findCurrentSlots(smartPlan);

    if (smartPlan && slot && (slot.type === 'study' || slot.type === 'lecture') && day) {
        setSessionPrompt({ slot, nextSlot, day });
    } else {
        setCustomizationRequest({ file, isUntracked: true });
    }
  };

  const handlePromptConfirm = async () => {
      if (file && sessionPrompt) {
          setCustomizationRequest({ file, slot: sessionPrompt.slot, isUntracked: false });
      }
      setSessionPrompt(null);
  };

  const handlePromptReject = async () => {
      if (file && sessionPrompt) {
          setConflictInfo({
              plannedSubject: sessionPrompt.slot.activity,
              uploadedSubject: file.context,
              day: sessionPrompt.day,
              slot: sessionPrompt.slot,
              file: file,
          });
          setShowConflictResolution(true);
      }
      setSessionPrompt(null);
  };

  const handleConflictResolution = (resolution: 'replace' | 'shift' | 'addExtra') => {
    if (!conflictInfo || !smartPlan) return;

    setShowConflictResolution(false);

    const { slot: currentSlot, day: currentDay, file: newFile, uploadedSubject } = conflictInfo;

    let newPlan = JSON.parse(JSON.stringify(smartPlan));
    const dayPlanIndex = newPlan.findIndex((d: any) => d.day === currentDay);
    if (dayPlanIndex === -1) return;

    const slotDuration = timeToMinutes(currentSlot.endTime) - timeToMinutes(currentSlot.startTime);
    let slotToCustomize = { ...currentSlot, activity: uploadedSubject, type: ActivityType.STUDY };

    if (resolution === 'replace') {
        const slotIndex = newPlan[dayPlanIndex].slots.findIndex((s: any) => s.startTime === currentSlot.startTime && s.activity === currentSlot.activity);
        if(slotIndex !== -1) newPlan[dayPlanIndex].slots[slotIndex] = slotToCustomize;
    } 
    else if (resolution === 'shift') {
        let shifted = false;
        for(let dayIdx = dayPlanIndex; dayIdx < newPlan.length; dayIdx++) {
            const slots = newPlan[dayIdx].slots;
            for(let slotIdx = 0; slotIdx < slots.length; slotIdx++){
                const slot = slots[slotIdx];
                if(slot.type === ActivityType.FREE){
                    const freeDuration = timeToMinutes(slot.endTime) - timeToMinutes(slot.startTime);
                    if (freeDuration >= slotDuration) {
                        const newStartTime = timeToMinutes(slot.startTime);
                        const newEndTime = newStartTime + slotDuration;
                        slotToCustomize = { ...slotToCustomize, startTime: minutesToTime(newStartTime), endTime: minutesToTime(newEndTime) };
                        const remainingFreeSlot: PlanSlot = { ...slot, startTime: minutesToTime(newEndTime) };
                        slots.splice(slotIdx, 1, slotToCustomize);
                        if (timeToMinutes(remainingFreeSlot.endTime) > newEndTime) {
                            slots.splice(slotIdx + 1, 0, remainingFreeSlot);
                        }
                        shifted = true;
                        break;
                    }
                }
            }
            if(shifted) break;
        }
        if(!shifted){
             addToast(t('toasts.noFreeSlot'), "warning");
             const lastSlot = newPlan[dayPlanIndex].slots[newPlan[dayPlanIndex].slots.length - 1];
             const newStartTime = timeToMinutes(lastSlot.endTime);
             slotToCustomize = {...slotToCustomize, startTime: minutesToTime(newStartTime), endTime: minutesToTime(newStartTime + slotDuration)};
             newPlan[dayPlanIndex].slots.push(slotToCustomize);
        }
    } else if (resolution === 'addExtra') {
       const slotIndex = newPlan[dayPlanIndex].slots.findIndex((s: any) => s.startTime === currentSlot.startTime && s.activity === currentSlot.activity);
        if(slotIndex !== -1) {
            newPlan[dayPlanIndex].slots.splice(slotIndex + 1, 0, slotToCustomize);
        } else {
            newPlan[dayPlanIndex].slots.push(slotToCustomize);
        }
    }

    setSmartPlan(newPlan);
    setConflictInfo(null);
    setCustomizationRequest({ file: newFile, slot: slotToCustomize, isUntracked: false });
  };

  const startSessionWithCustomDuration = (slot: PlanSlot, uploadedFile: UploadedFile, durationMinutes: number, breakConfig: { breakActivity: string; breakLink: string; breakDuration: number; breakPlacement: 'during' | 'after'; }, isUntracked: boolean) => {
    setFile(uploadedFile);

    const now = Date.now();
    const studyDurationMs = durationMinutes * 60 * 1000;
    const breakDurationMs = breakConfig.breakDuration * 60 * 1000;

    let sessionEndTime = now + studyDurationMs;
    let breakStartTime: number | undefined = undefined;

    if (breakConfig.breakPlacement === 'during' && breakDurationMs > 0) {
        sessionEndTime += breakDurationMs;
        breakStartTime = now + (studyDurationMs / 2);
    }

     const newSession: ActiveSession = {
        startTime: now,
        endTime: sessionEndTime,
        subject: slot.activity,
        type: ActivityType.STUDY,
        isUntracked,
        durationMinutes: durationMinutes,
        fromSlot: slot,
        nextSlot: breakConfig.breakDuration > 0 ? {
            activity: breakConfig.breakActivity,
            startTime: 'N/A', 
            endTime: 'N/A',
            type: ActivityType.BREAK,
            link: breakConfig.breakLink,
            durationMinutes: breakConfig.breakDuration
        } : null,
        breakPlacement: breakConfig.breakPlacement,
        breakStartsAt: breakStartTime,
    };
    setActiveSession(newSession);
  };

  const handleCustomizationConfirm = (config: { studyDuration: number; breakDuration: number; breakActivity: string; breakLink: string; breakPlacement: 'during' | 'after'; addToPlan: boolean }) => {
      if (!customizationRequest) return;
      const { file, slot: initialSlot, isUntracked } = customizationRequest;
      setCustomizationRequest(null);

      // Handle adding to plan if requested
      if (config.addToPlan && isUntracked && smartPlan) {
          const now = new Date();
          const day = getDayOfWeek(now);
          const startTime = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
          // Calculate end time based on duration
          const endTime = new Date(now.getTime() + config.studyDuration * 60000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

          const newSlot: PlanSlot = {
              activity: customizationRequest.file.context, // or subject
              startTime: startTime,
              endTime: endTime,
              type: ActivityType.STUDY,
              isLocked: false,
              durationMinutes: config.studyDuration
          };

          const updatedPlan = smartPlan.map(dayPlan => {
              if (dayPlan.day === day) {
                  return { ...dayPlan, slots: [...dayPlan.slots, newSlot] };
              }
              return dayPlan;
          });
          setSmartPlan(updatedPlan);
          addToast(t('toasts.timetableUpdated'), 'success');
      }

      const finalSlot: PlanSlot = initialSlot 
        ? { ...initialSlot, endTime: minutesToTime(timeToMinutes(initialSlot.startTime) + config.studyDuration) }
        : {
          activity: file.context,
          startTime: 'Now',
          endTime: 'Custom',
          type: ActivityType.STUDY,
      };

      startSessionWithCustomDuration(finalSlot, file, config.studyDuration, config, isUntracked);
  };

  const { getRootProps, getInputProps, isDragActive } = useDropzone({ onDrop, multiple: false, disabled: isProcessing });

  const handleAnalysis = async (mode: 'summarize' | 'explain' | 'read') => {
    if (!file || isProcessing) return;

    setAnalysisMode(mode);

    if (analysisResults[mode]) {
      if (mode === 'read') {
        setReadAloudState('interactive');
        setAnalysisMode('read-focus');
      }
      return;
    }

    setLearningHubState(prev => ({...prev, isProcessing: true, processingMessage: t(`uploadslides.loading.${mode}` as any)}));
    try {
      const filePart: ImagePart = { inlineData: { data: file.base64, mimeType: file.type } };
      let result = '';
      if (mode === 'summarize') {
        result = await summarizeDocument(filePart, file.context, { fast: true });
      } else if (mode === 'explain') {
        result = await explainDocument(filePart, file.context, { fast: true });
      } else if (mode === 'read') {
        // Use the 'fast' option to speed up text extraction for the Read Aloud feature, per user request.
        result = await extractTextFromDocument(filePart, { fast: true });
      }

      setAnalysisResult(mode, result);
    } catch (error: any) {
      addToast(error.message || `Failed to ${mode} document.`, 'error');
      setAnalysisMode('actions');
    } finally {
      setLearningHubState(prev => ({...prev, isProcessing: false, processingMessage: ''}));
      if (mode === 'read') {
        setReadAloudState('interactive');
        setAnalysisMode('read-focus');
      }
    }
  };

  const handleChatSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim() || !file) return;

    const userMessage = chatInput;
    const historyForApi: ChatTurn[] = [...chatHistory];

    setLearningHubState(prev => ({
        ...prev, 
        isProcessing: true,
        chatHistory: [...prev.chatHistory, { user: userMessage, blay: t('uploadslides.blayIsTyping') }]
    }));
    setChatInput('');

    try {
        const filePart: ImagePart | null = historyForApi.length === 0 
            ? { inlineData: { data: file.base64, mimeType: file.type } }
            : null;

        const stream = await chatWithDocumentStream(filePart, userMessage, historyForApi, file.context, smartPlan);

        let fullResponse = '';
        for await (const chunk of stream) {
            fullResponse += chunk.text;
            setLearningHubState(prev => {
                const newHistory = [...prev.chatHistory];
                if (newHistory.length > 0) {
                    newHistory[newHistory.length - 1] = { ...newHistory[newHistory.length - 1], blay: fullResponse };
                }
                return { ...prev, chatHistory: newHistory };
            });
        }
    } catch (error) {
        addToast(t('toasts.chatError'), 'error');
        setLearningHubState(prev => {
            const newHistory = [...prev.chatHistory];
            if (newHistory.length > 0) {
                 newHistory[newHistory.length - 1] = { ...newHistory[newHistory.length - 1], blay: t('toasts.chatError') };
            }
            return { ...prev, chatHistory: newHistory };
        });
    } finally {
        setLearningHubState(prev => ({...prev, isProcessing: false}));
    }
  };

  const clearFile = () => {
    handleStop();
    setLearningHubState({ file: null, analysisMode: 'none', analysisResults: { summarize: null, explain: null, read: null }, chatHistory: [], isProcessing: false, processingMessage: '' });
  };

  const saveToNotes = () => {
      const content = analysisResults[analysisMode as 'summarize' | 'explain' | 'read'];
      if (!file || !content || isProcessing) return;
      const newNote: Note = {
        id: Date.now().toString(),
        title: `${analysisMode.charAt(0).toUpperCase() + analysisMode.slice(1)}: ${file.name}`,
        content,
        subject: file.context,
        createdAt: new Date().toISOString(),
        isFavourite: false,
      };
      setNotes([newNote, ...notes]);
      addToast(t('toasts.savedToNotes'), 'success');
  }

  const copyContent = () => {
      const content = analysisResults[analysisMode as 'summarize' | 'explain' | 'read'];
      if (content) {
          navigator.clipboard.writeText(content).then(() => addToast(t('toasts.copied'), 'success'));
      }
  };

  const handleReadAloudClick = () => {
    handleAnalysis('read');
  };

  const handleEditMessage = (index: number) => {
      const turn = chatHistory[index];
      if(turn) {
          setEditingMessage({ index, text: turn.user });
      }
  };

  const handleCancelEdit = () => setEditingMessage(null);

  const handleSaveEdit = (index: number) => {
      if(!editingMessage) return;

      const updatedHistory = [...chatHistory];
      updatedHistory.splice(index); // Remove all turns from the edited message onwards

      setLearningHubState(prev => ({
          ...prev,
          chatHistory: updatedHistory,
      }));
      setChatInput(editingMessage.text);
      setEditingMessage(null);
  };

  const AnalysisView: React.FC = () => {
    const content = analysisResults[analysisMode as 'summarize' | 'explain' | 'read'];

    if (isProcessing && !content) return <LoadingIndicator message={processingMessage || ''} />;

    return (
        <div className="bg-gray-50 dark:bg-gray-800/50 rounded-xl p-6 flex-1 overflow-y-auto min-h-[300px]">
            <RichTextViewer content={content || t('uploadslides.noContent')} />
        </div>
    );
  };

  if (analysisMode === 'read-focus') {
      const topBarButtonClass = "p-2 rounded-full text-gray-700 dark:text-gray-200 hover:bg-black/10 dark:hover:bg-white/10 disabled:opacity-50 transition-colors";
      return (
           <div className="flex-1 flex flex-col relative bg-gray-200 dark:bg-gray-900 rounded-lg min-h-[500px]">
              <div
                  onMouseEnter={() => setIsHoveringTopBar(true)}
                  onMouseLeave={() => setIsHoveringTopBar(false)}
                  className="absolute top-2 left-1/2 -translate-x-1/2 z-20 flex items-center justify-between gap-8 px-4 py-2 bg-gray-100/80 dark:bg-gray-800/80 backdrop-blur-lg rounded-full shadow-xl border border-gray-300 dark:border-gray-700"
              >
                  <button onClick={() => { handleStop(); setAnalysisMode('actions'); }} className="flex items-center gap-2 px-3 py-1.5 text-sm font-medium bg-gray-100 dark:bg-gray-700 rounded-md hover:bg-gray-200 dark:hover:bg-gray-600">
                      <ArrowLeftIcon className="w-4 h-4" /> 
                  </button>

                  <div className="flex items-center gap-2">
                      <button onClick={() => { handlePlay(0); }} className={topBarButtonClass} title="Restart"><RefreshIcon className="w-5 h-5" /></button>
                      {readAloudState === 'playing' ? (
                          <button onClick={handlePause} className={topBarButtonClass} title="Pause"><PauseIcon className="w-5 h-5" /></button>
                      ) : (
                          <button onClick={readAloudState === 'paused' ? handleResume : () => handlePlay(0)} className={topBarButtonClass} title="Play"><PlayIcon className="w-5 h-5" /></button>
                      )}
                      <button onClick={handleStop} className={topBarButtonClass} title="Stop"><StopIcon className="w-5 h-5" /></button>
                  </div>

                  <div className="flex items-center gap-4 text-gray-700 dark:text-gray-300">
                      <div className="flex items-center gap-2">
                         <ZoomOutIcon className="w-5 h-5"/>
                         <input type="range" min="0.5" max="2.5" step="0.1" value={zoom} onChange={e => setZoom(parseFloat(e.target.value))} className="w-24 accent-primary" aria-label="Zoom"/>
                         <ZoomInIcon className="w-5 h-5"/>
                      </div>
                       <div className="flex items-center gap-2">
                          <span className="text-sm font-medium">{t('readAloud.speed')}</span>
                          <input type="range" min="0.5" max="2" step="0.1" value={readingSpeed} onChange={e => setReadingSpeed(parseFloat(e.target.value))} className="w-20 accent-primary" aria-label="Reading speed"/>
                      </div>
                       <div className="flex items-center gap-2">
                          <VolumeIcon className="w-5 h-5" />
                          <input type="range" min="0" max="1" step="0.1" value={readingVolume} onChange={e => setReadingVolume(parseFloat(e.target.value))} className="w-20 accent-primary" aria-label="Volume"/>
                      </div>
                  </div>
              </div>

              <div className="flex-1 overflow-hidden pt-16 grid grid-cols-2 gap-4 p-4">
                   <div className="h-full overflow-y-auto">
                      <FileViewer file={file} zoom={zoom} onZoomChange={setZoom} showControls={false} />
                   </div>
                   <div 
                      onMouseMove={handleMouseMove}
                      className="relative h-full group"
                  >
                       <div className="h-full overflow-y-auto bg-white dark:bg-gray-800 p-6 rounded-lg">
                          {isProcessing && !analysisResults.read ? (
                              <LoadingIndicator message={processingMessage || t('uploadslides.loading.read')} />
                          ) : (
                              <RichTextViewer content={analysisResults.read || t('uploadslides.loading.content' as any)} highlightCharIndex={highlightCharIndex} />
                          )}
                       </div>
                       <div
                          onMouseEnter={() => setIsHoveringPlaybackControls(true)}
                          onMouseLeave={() => setIsHoveringPlaybackControls(false)}
                          style={{ 
                              left: `${controlsPosition.x}px`, 
                              top: `${controlsPosition.y}px`,
                          }}
                          className={`absolute z-30 flex items-center gap-1 p-2 bg-gray-100/80 dark:bg-gray-800/80 backdrop-blur-lg rounded-full shadow-xl border border-gray-300 dark:border-gray-700 transition-opacity transform -translate-x-1/2 -translate-y-1/2 opacity-0 group-hover:opacity-100 ${isHoveringTopBar ? '!opacity-0' : ''}`}
                      >
                          {readAloudState === 'playing' && (
                              <button onClick={handlePause} className="p-3 text-gray-800 dark:text-white hover:bg-black/10 dark:hover:bg-white/10 rounded-full"><PauseIcon className="w-6 h-6" /></button>
                          )}
                          {(readAloudState === 'paused' || readAloudState === 'interactive') && !isProcessing && analysisResults.read && (
                              <button onClick={readAloudState === 'paused' ? handleResume : () => handlePlay(0)} className="p-3 text-gray-800 dark:text-white hover:bg-black/10 dark:hover:bg-white/10 rounded-full"><PlayIcon className="w-6 h-6" /></button>
                          )}
                          {(readAloudState === 'playing' || readAloudState === 'paused') && (
                              <button onClick={handleStop} className="p-3 text-gray-800 dark:text-white hover:bg-black/10 dark:hover:bg-white/10 rounded-full"><StopIcon className="w-6 h-6" /></button>
                          )}
                      </div>
                   </div>
              </div>
          </div>
      )
  }

    return (
        <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-xl p-3 sm:p-4 md:p-8 flex flex-col flex-1 relative" style={{ minHeight: '500px' }}>
            {/* Header */}
            <div className="flex justify-between items-start mb-4 sm:mb-6">
                <div className="flex-1 min-w-0 pr-2">
                    <h3 className="text-lg sm:text-xl font-bold text-gray-800 dark:text-white truncate">{file?.name}</h3>
                    <p className="text-xs sm:text-sm text-gray-500 truncate">{file?.context}</p>
                </div>
                {!isStudyModeView && (
                    <button 
                        onClick={clearFile} 
                        disabled={isProcessing} 
                        className="p-2 text-gray-400 hover:text-red-500 disabled:opacity-50 flex-shrink-0"
                    >
                        <CloseIcon className="w-5 h-5"/>
                    </button>
                )}
            </div>

            {/* Action Cards - MOBILE OPTIMIZED GRID */}
            <div className="grid grid-cols-2 sm:grid-cols-2 md:grid-cols-4 gap-3 sm:gap-4 mb-4 sm:mb-6">
                <ActionCard 
                    titleKey="uploadslides.actions.summarize" 
                    descKey="uploadslides.actions.summarize.desc" 
                    onClick={() => handleAnalysis('summarize')}
                    icon="📝"
                />
                <ActionCard 
                    titleKey="uploadslides.actions.explain" 
                    descKey="uploadslides.actions.explain.desc" 
                    onClick={() => handleAnalysis('explain')}
                    icon="💡"
                />
                <ActionCard 
                    titleKey="uploadslides.actions.chat" 
                    descKey="uploadslides.actions.chat.desc" 
                    onClick={() => setAnalysisMode('chat')}
                    icon="💬"
                />
                <ActionCard 
                    titleKey="uploadslides.actions.read" 
                    descKey="uploadslides.actions.read.desc" 
                    onClick={handleReadAloudClick}
                    icon="🔊"
                />
            </div>

            {/* Content Area - FIXED HEIGHT FOR MOBILE */}
            <div 
                className="flex-1 overflow-hidden flex flex-col relative" 
                style={{ minHeight: '400px', maxHeight: 'calc(100vh - 400px)' }}
            >
                <LoadingOverlay isLoading={isProcessing} message={processingMessage || ''} />

                {analysisMode !== 'none' && analysisMode !== 'actions' && (
                    <div className="h-full flex flex-col">
                        {/* Results Header */}
                        <div className="flex justify-between items-center mb-2 flex-shrink-0">
                            <h4 className="text-base sm:text-lg font-semibold capitalize">
                                {t('uploadslides.results.title', { mode: analysisMode })}
                            </h4>
                            {analysisMode !== 'chat' && (
                                <div className="flex items-center gap-2">
                                    <button 
                                        onClick={copyContent} 
                                        disabled={isProcessing || !analysisResults[analysisMode as 'summarize' | 'explain' | 'read']} 
                                        className="flex items-center gap-1 sm:gap-2 px-2 sm:px-3 py-1.5 text-xs sm:text-sm bg-gray-100 dark:bg-gray-700 rounded-md hover:bg-gray-200 dark:hover:bg-gray-600 disabled:opacity-50"
                                    >
                                        <CopyIcon className="w-3 h-3 sm:w-4 sm:h-4" /> 
                                        <span className="hidden sm:inline">{t('common.copy')}</span>
                                    </button>
                                    <button 
                                        onClick={saveToNotes} 
                                        disabled={isProcessing || !analysisResults[analysisMode as 'summarize' | 'explain' | 'read']} 
                                        className="flex items-center gap-1 sm:gap-2 px-2 sm:px-3 py-1.5 text-xs sm:text-sm bg-gray-100 dark:bg-gray-700 rounded-md hover:bg-gray-200 dark:hover:bg-gray-600 disabled:opacity-50"
                                    >
                                        <SaveIcon className="w-3 h-3 sm:w-4 sm:h-4" /> 
                                        <span className="hidden sm:inline">{t('common.saveToNotes')}</span>
                                    </button>
                                </div>
                            )}
                        </div>

                        {/* Content Display */}
                        {analysisMode === 'chat' ? (
                            <ChatView
                                chatHistory={chatHistory}
                                chatInput={chatInput}
                                setChatInput={setChatInput}
                                handleChatSubmit={handleChatSubmit}
                                isProcessing={isProcessing}
                                editingMessage={editingMessage}
                                setEditingMessage={setEditingMessage}
                                handleEditMessage={handleEditMessage}
                                handleCancelEdit={handleCancelEdit}
                                handleSaveEdit={handleSaveEdit}
                            />
                        ) : (
                            <AnalysisView />
                        )}
                    </div>
                )}

                {(analysisMode === 'none' || analysisMode === 'actions') && (
                    <div className="flex-1 flex items-center justify-center text-center text-gray-500 bg-gray-50 dark:bg-gray-800/50 rounded-xl">
                        <p className="text-sm sm:text-base px-4">{t('uploadslides.selectAction')}</p>
                    </div>
                )}
            </div>

            {/* Start Study Button */}
            {!isStudyModeView && !activeSession && file && (
                <div className="mt-4 sm:mt-6 text-center flex-shrink-0">
                    <button 
                        onClick={handleStartStudyRequest} 
                        className="w-full sm:w-auto px-6 sm:px-8 py-3 bg-primary text-primary-text font-bold text-base sm:text-lg rounded-xl shadow-lg hover:bg-primary-dark active:scale-95 transition-all"
                    >
                        {t('uploadslides.startStudySession')}
                    </button>
                </div>
            )}
        </div>
    );
};

export default UploadSlides;

import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import type { ActiveSession, UploadedFile, Toast, TrackedSession, LearningHubState, PlanSlot, View, UploadedMaterialInfo } from '../types.ts';
import { ActivityType } from '../types.ts';
import { useLanguage } from '../contexts/LanguageContext.tsx';
import { ExitIcon } from './icons/ExitIcon.tsx';
import { PlayIcon } from './icons/PlayIcon.tsx';
import { PauseIcon } from './icons/PauseIcon.tsx';
import { ClockIcon } from './icons/ClockIcon.tsx';
import { BookIcon } from './icons/BookIcon.tsx';
import { CoffeeIcon } from './icons/CoffeeIcon.tsx';
import ConfirmationModal from './ConfirmationModal.tsx';
import UploadSlides from './UploadSlides';
import SessionCompleteModal from './SessionCompleteModal.tsx';
import BreakView from './BreakView.tsx';
import { timeToMinutes } from '../lib/utils.ts';
import { notificationService } from '../services/notificationService.ts';

interface FocusedStudyViewProps {
    session: ActiveSession;
    setSession: (session: ActiveSession | null) => void;
    addToast: (message: string, type: 'success' | 'error' | 'info' | 'warning') => void;
    trackedData: TrackedSession[];
    setTrackedData: (data: TrackedSession[]) => void;
    setView: (view: View) => void;
    learningHubState: LearningHubState;
    setLearningHubState: React.Dispatch<React.SetStateAction<LearningHubState>>;
}

const MOTIVATIONAL_QUOTES = [
    { text: "Concentration is the root of all the higher abilities in man.", author: "Bruce Lee" },
    { text: "We are what we repeatedly do. Excellence, then, is not an act, but a habit.", author: "Aristotle" },
    { text: "Success is the sum of small efforts, repeated day in and day out.", author: "Robert Collier" },
    { text: "The future belongs to those who believe in the beauty of their dreams.", author: "Eleanor Roosevelt" },
    { text: "Don't watch the clock; do what it does. Keep going.", author: "Sam Levenson" },
    { text: "Start where you are. Use what you have. Do what you can.", author: "Arthur Ashe" },
    { text: "Education is the passport to the future, for tomorrow belongs to those who prepare for it today.", author: "Malcolm X" },
    { text: "Focus on being productive instead of busy.", author: "Tim Ferriss" },
    { text: "The only way to do great work is to love what you do.", author: "Steve Jobs" },
    { text: "It always seems impossible until it's done.", author: "Nelson Mandela" },
    { text: "Discipline is choosing between what you want now and what you want most.", author: "Abraham Lincoln" },
    { text: "Your time is limited, so don't waste it living someone else's life.", author: "Steve Jobs" },
    { text: "Action is the foundational key to all success.", author: "Pablo Picasso" }
];

const FocusedStudyView: React.FC<FocusedStudyViewProps> = ({ session, setSession, addToast, trackedData, setTrackedData, setView, learningHubState, setLearningHubState }) => {
    const { t } = useLanguage();

    const totalDurationSeconds = useMemo(() => {
        const duration = session.endTime - session.startTime;
        return duration > 0 ? Math.round(duration / 1000) : 0;
    }, [session.startTime, session.endTime]);

    const [timeLeft, setTimeLeft] = useState(() => Math.max(0, Math.round((session.endTime - Date.now()) / 1000)));
    const [isPaused, setIsPaused] = useState(false);
    const [isComplete, setIsComplete] = useState(false);
    const [isBreakActive, setIsBreakActive] = useState(false);
    const [breakTriggered, setBreakTriggered] = useState(false);
    const [showExitConfirm, setShowExitConfirm] = useState(false);
    const [sessionCompletedNaturally, setSessionCompletedNaturally] = useState(false);
    const [randomQuote, setRandomQuote] = useState(MOTIVATIONAL_QUOTES[0]);

    const pauseStartTimeRef = useRef<number>(0);

    // Select a random quote on mount
    useEffect(() => {
        const index = Math.floor(Math.random() * MOTIVATIONAL_QUOTES.length);
        setRandomQuote(MOTIVATIONAL_QUOTES[index]);
    }, []);

    const handleSessionEnd = useCallback((isEarlyTermination = false) => {
        if (isComplete) return; 
        setIsComplete(true);
        setSessionCompletedNaturally(!isEarlyTermination);

        // Play sound on completion
        notificationService.playAlarm();

        if (!session.isUntracked) {
            const timeStudiedMs = isEarlyTermination ? (totalDurationSeconds - timeLeft) * 1000 : totalDurationSeconds * 1000;
            const durationMinutes = Math.round(timeStudiedMs / (1000 * 60));

            if (durationMinutes > 0) {
                const newLog: TrackedSession = {
                    subject: session.subject,
                    durationMinutes,
                    date: new Date().toISOString().split('T')[0],
                };
                setTrackedData([...(trackedData || []), newLog]);
            }
        }
    }, [isComplete, session, totalDurationSeconds, timeLeft, trackedData, setTrackedData]);

    const handleStartNextBreakEarly = () => {
        if (!session.nextSlot || session.nextSlot.type !== 'break' || session.breakPlacement !== 'during') {
            addToast("No 'during-session' break is scheduled for this session.", "info");
            return;
        }

        // Don't end the current session. Just trigger the break state within it.
        // The session's total endTime already accounts for the break.
        // By updating breakStartsAt, we just change *when* the break happens.
        // The main timer will pause, and the break view will take over.
        setSession({
            ...session,
            breakStartsAt: Date.now(),
        });

        // Manually trigger the break UI and sound.
        setBreakTriggered(true);
        setIsBreakActive(true);
        notificationService.playAlarm();
    };

    const handleStartScheduledBreak = () => {
        if (session.nextSlot && session.nextSlot.type === 'break') {
            const breakSlot = session.nextSlot;
            const breakDurationMinutes = breakSlot.durationMinutes || (timeToMinutes(breakSlot.endTime) - timeToMinutes(breakSlot.startTime));

            if (breakDurationMinutes <= 0) {
                addToast("Scheduled break has no duration.", "warning");
                setSession(null);
                return;
            }

            const now = Date.now();
            const breakSession: ActiveSession = {
                startTime: now,
                endTime: now + breakDurationMinutes * 60 * 1000,
                subject: breakSlot.activity,
                type: 'break',
                fromSlot: breakSlot,
                nextSlot: null,
                isUntracked: session.isUntracked,
                postBreakView: learningHubState.file ? 'uploadslides' : undefined,
            };

            // Play start sound for break
            notificationService.playAlarm();
            setSession(breakSession);
        }
    };

    const handleBreakEnd = useCallback((skipped?: boolean) => {
        if (skipped && session.breakPlacement === 'during' && session.nextSlot?.type === 'break' && session.breakStartsAt) {
            const breakDurationMs = (session.nextSlot.durationMinutes || 0) * 60 * 1000;
            if (breakDurationMs > 0) {
                const breakTimeUsedMs = Date.now() - session.breakStartsAt;
                const timeSavedMs = Math.max(0, breakDurationMs - breakTimeUsedMs);
                setSession({
                    ...session,
                    endTime: session.endTime - timeSavedMs
                });
            }
        }
        setIsBreakActive(false);
        // Play resume sound
        notificationService.playAlarm();
    }, [session, setSession]);


    useEffect(() => {
        if (isPaused || isComplete || isBreakActive) return;

        const timerId = setInterval(() => {
            const remaining = Math.round((session.endTime - Date.now()) / 1000);

            if (remaining <= 0) {
                clearInterval(timerId);
                handleSessionEnd(false);
                return;
            }
            setTimeLeft(remaining);

            if (session.breakPlacement === 'during' && session.breakStartsAt && !breakTriggered && Date.now() >= session.breakStartsAt) {
                setBreakTriggered(true);
                setIsBreakActive(true);
                notificationService.playAlarm();
            }
        }, 1000);

        return () => clearInterval(timerId);
    }, [session.endTime, session.breakStartsAt, isPaused, isComplete, isBreakActive, breakTriggered, handleSessionEnd]);

    const togglePause = useCallback(() => {
        setIsPaused(prev => {
            if (!prev) {
                pauseStartTimeRef.current = Date.now();
                addToast(t('toasts.sessionPaused'), 'info');
            } else {
                const pausedDuration = Date.now() - pauseStartTimeRef.current;
                setSession({ 
                    ...session, 
                    endTime: session.endTime + pausedDuration,
                    breakStartsAt: session.breakStartsAt ? session.breakStartsAt + pausedDuration : undefined
                });
                addToast(t('toasts.sessionResumed'), 'success');
            }
            return !prev;
        });
    }, [addToast, t, session, setSession]);

    const breakSessionForView = useMemo((): ActiveSession | null => {
        if ((isBreakActive || (isComplete && session.breakPlacement === 'after')) && session.nextSlot?.type === 'break') {
            const durationMs = (session.nextSlot.durationMinutes || 10) * 60 * 1000;
            return {
                startTime: Date.now(),
                endTime: Date.now() + durationMs,
                subject: session.nextSlot.activity,
                type: 'break',
                fromSlot: session.nextSlot,
                nextSlot: null,
                day: session.day
            };
        }
        return null;
    }, [isBreakActive, isComplete, session.breakPlacement, session.nextSlot, session.day]);

    const formatTime = (seconds: number) => {
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
    };

    const studyProgress = totalDurationSeconds > 0 ? ((totalDurationSeconds - timeLeft) / totalDurationSeconds) * 100 : 0;

    const dummySetState = () => {};
    const learningHubFile = learningHubState.file;

    const handleNavigate = (target: 'dashboard' | 'uploadslides') => {
        setIsComplete(false);
        setSession(null);
        setView(target);
    };

    if (isComplete) {
        return <SessionCompleteModal 
                    isOpen={isComplete} 
                    onNavigate={handleNavigate}
                    session={session} 
                    wasTracked={!session.isUntracked} 
                    onStartBreak={session.breakPlacement === 'after' && session.nextSlot?.type === 'break' ? handleStartScheduledBreak : undefined} 
               />;
    }

    return (
        <>
            <div className="fixed inset-0 bg-white dark:bg-gray-900 z-[100] flex flex-col">
                <header className="bg-white dark:bg-gray-800 border-b dark:border-gray-700 shadow-lg">
                    <div className="flex items-center justify-between p-4">
                         <div className="flex items-center gap-4">
                            <BookIcon className="w-8 h-8 text-primary dark:text-primary-light" />
                            <div>
                                <h2 className="text-xl font-bold text-gray-800 dark:text-white">
                                    {t('focusedStudy.title')}
                                </h2>
                                <p className="text-sm text-gray-600 dark:text-gray-400">
                                    {session.subject} • {session.isUntracked ? t('focusedStudy.untracked') : t('focusedStudy.scheduled')}
                                </p>
                            </div>
                        </div>
                        <div className="flex items-center gap-6">
                            <div className="text-center">
                                <div className="flex items-center gap-2 text-2xl font-bold text-primary dark:text-primary-light">
                                    <ClockIcon className="w-6 h-6" />
                                    {formatTime(timeLeft)}
                                </div>
                                <div className="text-sm text-gray-500">
                                    {studyProgress.toFixed(0)}{t('focusedStudy.complete')}
                                </div>
                            </div>

                            <div className="flex items-center gap-3">
                                <button onClick={togglePause} disabled={isBreakActive} className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-all ${isPaused ? 'bg-green-100 dark:bg-green-900/20 text-green-600 dark:text-green-400 hover:bg-green-200' : 'bg-yellow-100 dark:bg-yellow-900/20 text-yellow-600 dark:text-yellow-400 hover:bg-yellow-200'} disabled:opacity-50`}>
                                    {isPaused ? <><PlayIcon className="w-4 h-4" />{t('focusedStudy.resume')}</> : <><PauseIcon className="w-4 h-4" />{t('focusedStudy.pause')}</>}
                                </button>
                                {session.breakPlacement === 'during' && session.nextSlot?.type === 'break' && (
                                    <button
                                        onClick={handleStartNextBreakEarly}
                                        disabled={isBreakActive}
                                        className="flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-all bg-blue-100 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 hover:bg-blue-200 disabled:opacity-50"
                                        title={`Start your '${session.nextSlot.activity}' break now`}
                                    >
                                        <CoffeeIcon className="w-4 h-4" /> {t('focusedStudy.startBreak')}
                                    </button>
                                )}
                                <button onClick={() => setShowExitConfirm(true)} className="flex items-center gap-2 px-4 py-2 text-white bg-red-600 rounded-lg hover:bg-red-700 transition-all">
                                    <ExitIcon className="w-4 h-4" />
                                    {t('focusedStudy.exit')}
                                </button>
                            </div>
                        </div>
                    </div>
                    <div className="w-full bg-gray-200 dark:bg-gray-700 h-2">
                        <div className="bg-primary h-2 transition-all duration-300" style={{ width: `${studyProgress}%` }} />
                    </div>
                </header>

                <main className="flex-1 overflow-y-auto bg-gray-50 dark:bg-gray-800 p-4">
                     {isPaused ? (
                        <div className="h-full flex items-center justify-center">
                            <div className="text-center">
                                <div className="text-6xl mb-4">⏸️</div>
                                <h3 className="text-2xl font-bold text-gray-600 dark:text-gray-400 mb-2">{t('focusedStudy.paused.title')}</h3>
                                <p className="text-gray-500 dark:text-gray-500 mb-6">{t('focusedStudy.paused.body')}</p>
                                <button onClick={togglePause} className="flex items-center gap-2 px-6 py-3 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-all mx-auto">
                                    <PlayIcon className="w-5 h-5" />
                                    {t('focusedStudy.paused.button')}
                                </button>
                            </div>
                        </div>
                    ) : learningHubFile ? (
                        <UploadSlides
                            smartPlan={null}
                            setSmartPlan={dummySetState as any}
                            activeSession={session}
                            setActiveSession={setSession}
                            setView={setView}
                            addToast={addToast}
                            learningHubState={learningHubState}
                            setLearningHubState={setLearningHubState}
                            notes={[]}
                            setNotes={dummySetState as any}
                            showTitle={false}
                            isStudyModeView={true}
                            intendedStudyContext={null}
                            setIntendedStudyContext={dummySetState as any}
                            onAttemptUpload={(file: File) => {
                                addToast('Cannot upload new materials during a focused study session.', 'info');
                            }}
                        />
                    ) : (
                        <div className="h-full flex items-center justify-center text-center text-gray-500 bg-gray-100 dark:bg-gray-800/50 rounded-lg">
                            <div className="p-8">
                                <BookIcon className="w-20 h-20 mx-auto text-gray-400 dark:text-gray-500 mb-6" />
                                <h3 className="text-2xl font-bold text-gray-800 dark:text-gray-200">
                                    {t('focusedStudy.focusMode.title')}
                                </h3>
                                <p className="text-lg text-gray-600 dark:text-gray-400 mt-2">
                                    {session.subject}
                                </p>
                                <div className="mt-12 max-w-lg mx-auto">
                                    <p className="text-xl font-serif italic text-gray-600 dark:text-gray-300">
                                        "{randomQuote.text}"
                                    </p>
                                    <p className="text-sm font-semibold text-gray-500 dark:text-gray-400 mt-3">
                                        - {randomQuote.author}
                                    </p>
                                </div>
                            </div>
                        </div>
                    )}
                </main>
            </div>

            {isBreakActive && breakSessionForView && (
                <BreakView session={breakSessionForView} onEnd={handleBreakEnd} />
            )}

            <ConfirmationModal
                isOpen={showExitConfirm}
                onClose={() => setShowExitConfirm(false)}
                onConfirm={() => { handleSessionEnd(true); }}
                title={t('confirmation.exitStudy.title')}
                message={t('confirmation.exitStudy.message', { subject: session.subject })}
                confirmText={t('confirmation.exitStudy.confirm')}
                cancelText={t('confirmation.exitStudy.cancel')}
                confirmColor="red"
            />
        </>
    );
};

export default FocusedStudyView;

