                      </div>
                       <div className="flex items-center gap-2">
                          <VolumeIcon className="w-5 h-5" />
                          <input type="range" min="0" max="1" step="0.1" value={readingVolume} onChange={e => setReadingVolume(parseFloat(e.target.value))} className="w-20 accent-primary" aria-label="Volume"/>
                      </div>
                  </div>
              </div>

              <div className="flex-1 overflow-hidden pt-16 grid grid-cols-2 gap-4 p-4">
                   <div className="h-full overflow-y-auto">
                      <FileViewer file={file} zoom={zoom} onZoomChange={setZoom} showControls={false} />
                   </div>
                   <div 
                      onMouseMove={handleMouseMove}
                      className="relative h-full group"
                  >
                       <div className="h-full overflow-y-auto bg-white dark:bg-gray-800 p-6 rounded-lg">
                          {isProcessing && !analysisResults.read ? (
                              <LoadingIndicator message={processingMessage || t('uploadslides.loading.read')} />
                          ) : (
                              <RichTextViewer content={analysisResults.read || t('uploadslides.loading.content' as any)} highlightCharIndex={highlightCharIndex} />
                          )}
                       </div>
                       <div
                          onMouseEnter={() => setIsHoveringPlaybackControls(true)}
                          onMouseLeave={() => setIsHoveringPlaybackControls(false)}
                          style={{ 
                              left: `${controlsPosition.x}px`, 
                              top: `${controlsPosition.y}px`,
                          }}
                          className={`absolute z-30 flex items-center gap-1 p-2 bg-gray-100/80 dark:bg-gray-800/80 backdrop-blur-lg rounded-full shadow-xl border border-gray-300 dark:border-gray-700 transition-opacity transform -translate-x-1/2 -translate-y-1/2 opacity-0 group-hover:opacity-100 ${isHoveringTopBar ? '!opacity-0' : ''}`}
                      >
                          {readAloudState === 'playing' && (
                              <button onClick={handlePause} className="p-3 text-gray-800 dark:text-white hover:bg-black/10 dark:hover:bg-white/10 rounded-full"><PauseIcon className="w-6 h-6" /></button>
                          )}
                          {(readAloudState === 'paused' || readAloudState === 'interactive') && !isProcessing && analysisResults.read && (
                              <button onClick={readAloudState === 'paused' ? handleResume : () => handlePlay(0)} className="p-3 text-gray-800 dark:text-white hover:bg-black/10 dark:hover:bg-white/10 rounded-full"><PlayIcon className="w-6 h-6" /></button>
                          )}
                          {(readAloudState === 'playing' || readAloudState === 'paused') && (
                              <button onClick={handleStop} className="p-3 text-gray-800 dark:text-white hover:bg-black/10 dark:hover:bg-white/10 rounded-full"><StopIcon className="w-6 h-6" /></button>
                          )}
                      </div>
                   </div>
              </div>
          </div>
      )
  }

    return (
        <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-xl p-3 sm:p-4 md:p-8 flex flex-col flex-1 relative" style={{ minHeight: '500px' }}>
            {/* Header */}
            <div className="flex justify-between items-start mb-4 sm:mb-6">
                <div className="flex-1 min-w-0 pr-2">
                    <h3 className="text-lg sm:text-xl font-bold text-gray-800 dark:text-white truncate">{file?.name}</h3>
                    <p className="text-xs sm:text-sm text-gray-500 truncate">{file?.context}</p>
                </div>
                {!isStudyModeView && (
                    <button 
                        onClick={clearFile} 
                        disabled={isProcessing} 
                        className="p-2 text-gray-400 hover:text-red-500 disabled:opacity-50 flex-shrink-0"
                    >
                        <CloseIcon className="w-5 h-5"/>
                    </button>
                )}
            </div>

            {/* Action Cards - MOBILE OPTIMIZED GRID */}
            <div className="grid grid-cols-2 sm:grid-cols-2 md:grid-cols-4 gap-3 sm:gap-4 mb-4 sm:mb-6">
                <ActionCard 
                    titleKey="uploadslides.actions.summarize" 
                    descKey="uploadslides.actions.summarize.desc" 
                    onClick={() => handleAnalysis('summarize')}
                    icon="📝"
                />
                <ActionCard 
                    titleKey="uploadslides.actions.explain" 
                    descKey="uploadslides.actions.explain.desc" 
                    onClick={() => handleAnalysis('explain')}
                    icon="💡"
                />
                <ActionCard 
                    titleKey="uploadslides.actions.chat" 
                    descKey="uploadslides.actions.chat.desc" 
                    onClick={() => setAnalysisMode('chat')}
                    icon="💬"
                />
                <ActionCard 
                    titleKey="uploadslides.actions.read" 
                    descKey="uploadslides.actions.read.desc" 
                    onClick={handleReadAloudClick}
                    icon="🔊"
                />
            </div>

            {/* Content Area - FIXED HEIGHT FOR MOBILE */}
            <div 
                className="flex-1 overflow-hidden flex flex-col relative" 
                style={{ minHeight: '400px', maxHeight: 'calc(100vh - 400px)' }}
            >
                <LoadingOverlay isLoading={isProcessing} message={processingMessage || ''} />

                {analysisMode !== 'none' && analysisMode !== 'actions' && (
                    <div className="h-full flex flex-col">
                        {/* Results Header */}
                        <div className="flex justify-between items-center mb-2 flex-shrink-0">
                            <h4 className="text-base sm:text-lg font-semibold capitalize">
                                {t('uploadslides.results.title', { mode: analysisMode })}
                            </h4>
                            {analysisMode !== 'chat' && (
                                <div className="flex items-center gap-2">
                                    <button 
                                        onClick={copyContent} 
                                        disabled={isProcessing || !analysisResults[analysisMode as 'summarize' | 'explain' | 'read']} 
                                        className="flex items-center gap-1 sm:gap-2 px-2 sm:px-3 py-1.5 text-xs sm:text-sm bg-gray-100 dark:bg-gray-700 rounded-md hover:bg-gray-200 dark:hover:bg-gray-600 disabled:opacity-50"
                                    >
                                        <CopyIcon className="w-3 h-3 sm:w-4 sm:h-4" /> 
                                        <span className="hidden sm:inline">{t('common.copy')}</span>
                                    </button>
                                    <button 
                                        onClick={saveToNotes} 
                                        disabled={isProcessing || !analysisResults[analysisMode as 'summarize' | 'explain' | 'read']} 
                                        className="flex items-center gap-1 sm:gap-2 px-2 sm:px-3 py-1.5 text-xs sm:text-sm bg-gray-100 dark:bg-gray-700 rounded-md hover:bg-gray-200 dark:hover:bg-gray-600 disabled:opacity-50"
                                    >
                                        <SaveIcon className="w-3 h-3 sm:w-4 sm:h-4" /> 
                                        <span className="hidden sm:inline">{t('common.saveToNotes')}</span>
                                    </button>
                                </div>
                            )}
                        </div>

                        {/* Content Display */}
                        {analysisMode === 'chat' ? (
                            <ChatView
                                chatHistory={chatHistory}
                                chatInput={chatInput}
                                setChatInput={setChatInput}
                                handleChatSubmit={handleChatSubmit}
                                isProcessing={isProcessing}
                                editingMessage={editingMessage}
                                setEditingMessage={setEditingMessage}
                                handleEditMessage={handleEditMessage}
                                handleCancelEdit={handleCancelEdit}
                                handleSaveEdit={handleSaveEdit}
                            />
                        ) : (
                            <AnalysisView />
                        )}
                    </div>
                )}

                {(analysisMode === 'none' || analysisMode === 'actions') && (
                    <div className="flex-1 flex items-center justify-center text-center text-gray-500 bg-gray-50 dark:bg-gray-800/50 rounded-xl">
                        <p className="text-sm sm:text-base px-4">{t('uploadslides.selectAction')}</p>
                    </div>
                )}
            </div>

            {/* Start Study Button */}
            {!isStudyModeView && !activeSession && file && (
                <div className="mt-4 sm:mt-6 text-center flex-shrink-0">
                    <button 
                        onClick={handleStartStudyRequest} 
                        className="w-full sm:w-auto px-6 sm:px-8 py-3 bg-primary text-primary-text font-bold text-base sm:text-lg rounded-xl shadow-lg hover:bg-primary-dark active:scale-95 transition-all"
                    >
                        {t('uploadslides.startStudySession')}
                    </button>
                </div>
            )}
        </div>
    );
};

export default UploadSlides;

import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import type { ActiveSession, UploadedFile, Toast, TrackedSession, LearningHubState, PlanSlot, View, UploadedMaterialInfo } from '../types.ts';
import { ActivityType } from '../types.ts';
import { useLanguage } from '../contexts/LanguageContext.tsx';
import { ExitIcon } from './icons/ExitIcon.tsx';
import { PlayIcon } from './icons/PlayIcon.tsx';
import { PauseIcon } from './icons/PauseIcon.tsx';
import { ClockIcon } from './icons/ClockIcon.tsx';
import { BookIcon } from './icons/BookIcon.tsx';
import { CoffeeIcon } from './icons/CoffeeIcon.tsx';
import ConfirmationModal from './ConfirmationModal.tsx';
import UploadSlides from './UploadSlides';
import SessionCompleteModal from './SessionCompleteModal.tsx';
import BreakView from './BreakView.tsx';
import { timeToMinutes } from '../lib/utils.ts';
import { notificationService } from '../services/notificationService.ts';

interface FocusedStudyViewProps {
    session: ActiveSession;
    setSession: (session: ActiveSession | null) => void;
    addToast: (message: string, type: 'success' | 'error' | 'info' | 'warning') => void;
    trackedData: TrackedSession[];
    setTrackedData: (data: TrackedSession[]) => void;
    setView: (view: View) => void;
    learningHubState: LearningHubState;
    setLearningHubState: React.Dispatch<React.SetStateAction<LearningHubState>>;
}

const MOTIVATIONAL_QUOTES = [
    { text: "Concentration is the root of all the higher abilities in man.", author: "Bruce Lee" },
    { text: "We are what we repeatedly do. Excellence, then, is not an act, but a habit.", author: "Aristotle" },
    { text: "Success is the sum of small efforts, repeated day in and day out.", author: "Robert Collier" },
    { text: "The future belongs to those who believe in the beauty of their dreams.", author: "Eleanor Roosevelt" },
    { text: "Don't watch the clock; do what it does. Keep going.", author: "Sam Levenson" },
    { text: "Start where you are. Use what you have. Do what you can.", author: "Arthur Ashe" },
    { text: "Education is the passport to the future, for tomorrow belongs to those who prepare for it today.", author: "Malcolm X" },
    { text: "Focus on being productive instead of busy.", author: "Tim Ferriss" },
    { text: "The only way to do great work is to love what you do.", author: "Steve Jobs" },
    { text: "It always seems impossible until it's done.", author: "Nelson Mandela" },
    { text: "Discipline is choosing between what you want now and what you want most.", author: "Abraham Lincoln" },
    { text: "Your time is limited, so don't waste it living someone else's life.", author: "Steve Jobs" },
    { text: "Action is the foundational key to all success.", author: "Pablo Picasso" }
];

const FocusedStudyView: React.FC<FocusedStudyViewProps> = ({ session, setSession, addToast, trackedData, setTrackedData, setView, learningHubState, setLearningHubState }) => {
    const { t } = useLanguage();

    const totalDurationSeconds = useMemo(() => {
        const duration = session.endTime - session.startTime;
        return duration > 0 ? Math.round(duration / 1000) : 0;
    }, [session.startTime, session.endTime]);

    const [timeLeft, setTimeLeft] = useState(() => Math.max(0, Math.round((session.endTime - Date.now()) / 1000)));
    const [isPaused, setIsPaused] = useState(false);
    const [isComplete, setIsComplete] = useState(false);
    const [isBreakActive, setIsBreakActive] = useState(false);
    const [breakTriggered, setBreakTriggered] = useState(false);
    const [showExitConfirm, setShowExitConfirm] = useState(false);
    const [sessionCompletedNaturally, setSessionCompletedNaturally] = useState(false);
    const [randomQuote, setRandomQuote] = useState(MOTIVATIONAL_QUOTES[0]);

    const pauseStartTimeRef = useRef<number>(0);

    // Select a random quote on mount
    useEffect(() => {
        const index = Math.floor(Math.random() * MOTIVATIONAL_QUOTES.length);
        setRandomQuote(MOTIVATIONAL_QUOTES[index]);
    }, []);

    const handleSessionEnd = useCallback((isEarlyTermination = false) => {
        if (isComplete) return; 
        setIsComplete(true);
        setSessionCompletedNaturally(!isEarlyTermination);

        // Play sound on completion
        notificationService.playAlarm();

        if (!session.isUntracked) {
            const timeStudiedMs = isEarlyTermination ? (totalDurationSeconds - timeLeft) * 1000 : totalDurationSeconds * 1000;
            const durationMinutes = Math.round(timeStudiedMs / (1000 * 60));

            if (durationMinutes > 0) {
                const newLog: TrackedSession = {
                    subject: session.subject,
                    durationMinutes,
                    date: new Date().toISOString().split('T')[0],
                };
                setTrackedData([...(trackedData || []), newLog]);
            }
        }
    }, [isComplete, session, totalDurationSeconds, timeLeft, trackedData, setTrackedData]);

    const handleStartNextBreakEarly = () => {
        if (!session.nextSlot || session.nextSlot.type !== 'break' || session.breakPlacement !== 'during') {
            addToast("No 'during-session' break is scheduled for this session.", "info");
            return;
        }

        // Don't end the current session. Just trigger the break state within it.
        // The session's total endTime already accounts for the break.
        // By updating breakStartsAt, we just change *when* the break happens.
        // The main timer will pause, and the break view will take over.
        setSession({
            ...session,
            breakStartsAt: Date.now(),
        });

        // Manually trigger the break UI and sound.
        setBreakTriggered(true);
        setIsBreakActive(true);
        notificationService.playAlarm();
    };

    const handleStartScheduledBreak = () => {
        if (session.nextSlot && session.nextSlot.type === 'break') {
            const breakSlot = session.nextSlot;
            const breakDurationMinutes = breakSlot.durationMinutes || (timeToMinutes(breakSlot.endTime) - timeToMinutes(breakSlot.startTime));

            if (breakDurationMinutes <= 0) {
                addToast("Scheduled break has no duration.", "warning");
                setSession(null);
                return;
            }

            const now = Date.now();
            const breakSession: ActiveSession = {
                startTime: now,
                endTime: now + breakDurationMinutes * 60 * 1000,
                subject: breakSlot.activity,
                type: 'break',
                fromSlot: breakSlot,
                nextSlot: null,
                isUntracked: session.isUntracked,
                postBreakView: learningHubState.file ? 'uploadslides' : undefined,
            };

            // Play start sound for break
            notificationService.playAlarm();
            setSession(breakSession);
        }
    };

    const handleBreakEnd = useCallback((skipped?: boolean) => {
        if (skipped && session.breakPlacement === 'during' && session.nextSlot?.type === 'break' && session.breakStartsAt) {
            const breakDurationMs = (session.nextSlot.durationMinutes || 0) * 60 * 1000;
            if (breakDurationMs > 0) {
                const breakTimeUsedMs = Date.now() - session.breakStartsAt;
                const timeSavedMs = Math.max(0, breakDurationMs - breakTimeUsedMs);
                setSession({
                    ...session,
                    endTime: session.endTime - timeSavedMs
                });
            }
        }
        setIsBreakActive(false);
        // Play resume sound
        notificationService.playAlarm();
    }, [session, setSession]);


    useEffect(() => {
        if (isPaused || isComplete || isBreakActive) return;

        const timerId = setInterval(() => {
            const remaining = Math.round((session.endTime - Date.now()) / 1000);

            if (remaining <= 0) {
                clearInterval(timerId);
                handleSessionEnd(false);
                return;
            }
            setTimeLeft(remaining);

            if (session.breakPlacement === 'during' && session.breakStartsAt && !breakTriggered && Date.now() >= session.breakStartsAt) {
                setBreakTriggered(true);
                setIsBreakActive(true);
                notificationService.playAlarm();
            }
        }, 1000);

        return () => clearInterval(timerId);
    }, [session.endTime, session.breakStartsAt, isPaused, isComplete, isBreakActive, breakTriggered, handleSessionEnd]);

    const togglePause = useCallback(() => {
        setIsPaused(prev => {
            if (!prev) {
                pauseStartTimeRef.current = Date.now();
                addToast(t('toasts.sessionPaused'), 'info');
            } else {
                const pausedDuration = Date.now() - pauseStartTimeRef.current;
                setSession({ 
                    ...session, 
                    endTime: session.endTime + pausedDuration,
                    breakStartsAt: session.breakStartsAt ? session.breakStartsAt + pausedDuration : undefined
                });
                addToast(t('toasts.sessionResumed'), 'success');
