                                        <div className="bg-primary text-primary-text p-3 sm:p-3 rounded-2xl rounded-tr-sm inline-block break-words text-sm sm:text-base">
                                            {turn.user}
                                        </div>
                                        <div className="absolute top-1/2 -translate-y-1/2 left-0 -translate-x-full hidden sm:flex items-center gap-1 p-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <div className="relative group/tooltip">
                                                <button onClick={() => handleEditMessage(i)} className={buttonClass}>
                                                    <PencilIcon className="w-4 h-4" />
                                                </button>
                                                <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 w-max px-2 py-1 text-xs font-semibold text-white bg-gray-900/80 dark:bg-black/80 rounded-md shadow-lg opacity-0 group-hover/tooltip:opacity-100 transition-opacity duration-200 z-10 pointer-events-none">
                                                    {t('common.edit')}
                                                </div>
                                            </div>
                                            <CopyButtonWithTooltip textToCopy={turn.user} className={buttonClass} />
                                        </div>
                                    </div>
                                </div>
                                {/* Blay's message */}
                                <div className="flex justify-start">
                                    <div className="group relative max-w-[85%] sm:max-w-[80%]">
                                        <div className="bg-white dark:bg-gray-700 p-3 sm:p-3 rounded-2xl rounded-tl-sm inline-block break-words text-left shadow-md">
                                            <RichTextViewer content={turn.blay} />
                                        </div>
                                        <div className="absolute top-1/2 -translate-y-1/2 right-0 translate-x-full hidden sm:flex items-center gap-1 p-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <CopyButtonWithTooltip textToCopy={turn.blay} className={buttonClass} />
                                        </div>
                                    </div>
                                </div>
                            </div>
                        );
                    })
                )}
                <div ref={chatEndRef} />
            </div>

            {/* Input Area - MOBILE OPTIMIZED WITH FIXED POSITIONING */}
            <div className="flex-shrink-0 border-t dark:border-gray-700 bg-white dark:bg-gray-800 p-3 sm:p-4">
                <form onSubmit={handleChatSubmit} className="flex gap-2">
                    <input 
                        ref={inputRef}
                        type="text" 
                        value={chatInput} 
                        onChange={e => setChatInput(e.target.value)} 
                        onKeyPress={(e) => {
                            if (e.key === 'Enter' && !e.shiftKey) {
                                e.preventDefault();
                                handleChatSubmit(e);
                            }
                        }}
                        disabled={isProcessing} 
                        className="flex-1 px-3 sm:px-4 py-2.5 sm:py-3 bg-gray-50 dark:bg-gray-900 border border-gray-300 dark:border-gray-700 rounded-xl text-gray-900 dark:text-gray-100 placeholder-gray-400 shadow-sm focus:outline-none focus:ring-2 focus:ring-primary focus:border-primary disabled:opacity-50 text-base"
                        placeholder={t('uploadslides.chat.placeholder')} 
                        style={{ fontSize: '16px' }} /* Prevents iOS zoom */
                    />
                    <button 
                        type="submit" 
                        disabled={isProcessing || !chatInput.trim()} 
                        className="px-4 sm:px-6 py-2.5 sm:py-3 bg-primary text-primary-text rounded-xl disabled:opacity-50 disabled:cursor-not-allowed font-medium shadow-md hover:shadow-lg active:scale-95 transition-all text-sm sm:text-base whitespace-nowrap flex items-center justify-center min-w-[70px]"
                    >
                        {isProcessing ? (
                            <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                        ) : (
                            t('uploadslides.chat.send')
                        )}
                    </button>
                </form>
            </div>
        </div>
    );
};

